def render_bsjp_cards(
    rows:         list,
    date_label:   str = "",
    generated_at: str = "",
    max_cards:    int = 10,
) -> None:
    """
    Render kartu BSJP dark-terminal ke Streamlit via components.html.

    Parameters
    ----------
    rows         : List dict dari _rule_based_plan / _rule_based_plan_v2
    date_label   : Tanggal plan (misal "01 Mei 2026")
    generated_at : Timestamp generate (misal "01 Mei 2026, 15:42 WIB")
    max_cards    : Batas maksimum kartu ditampilkan (default 10)
    """
    now    = _wib_now()
    hari   = ["SENIN","SELASA","RABU","KAMIS","JUMAT","SABTU","MINGGU"][now.weekday()]
    bulan  = ["JAN","FEB","MAR","APR","MEI","JUN","JUL","AGS","SEP","OKT","NOV","DES"][now.month-1]
    today  = f"{hari} · {now.day:02d} {bulan} {now.year}"

    n_all  = len(rows)
    n_show = min(n_all, max_cards)

    cards_html = ""
    for i, row in enumerate(rows[:n_show]):
        cards_html += _single_card_html(row, i)

    footer_note = f"{n_show} dari {n_all} kandidat" if n_all > n_show else f"{n_show} rekomendasi"
    if generated_at:
        footer_note += f" · {generated_at}"

    full_html = f"""<!DOCTYPE html>
<html>
<head>
<meta name="viewport" content="width=device-width,initial-scale=1.0">
{_CARD_CSS}
</head>
<body style="background:transparent;">

<div class="bsjp-wrap">

  <div class="bsjp-head">
    <span class="bsjp-head-title">BSJP &middot; TRADE PLAN</span>
    <span class="bsjp-head-date">{today}{(' &middot; ' + date_label) if date_label else ''}</span>
  </div>

  <div class="bsjp-grid">
    {cards_html}
  </div>

  <div class="bsjp-footer">
    <span class="bsjp-footer-note">{footer_note} &middot; HAKA = Hajar Kanan mendekati Closing &middot; Max 10 saham</span>
  </div>

</div>

</body>
</html>"""

    # Estimasi tinggi
    # FIX: mobile lebar ~360px → 1 kolom; desktop 720px+ → 2-3 kolom
    # Gunakan 1 kolom sebagai estimasi safe agar card tidak terpotong di mobile
    # (di desktop height lebih besar dari perlu, tapi itu lebih baik dari terpotong)
    cols_est   = 1  # selalu estimasi 1 kolom agar mobile tidak terpotong
    rows_est   = math.ceil(n_show / cols_est)
    # Bug#9 fix: estimasi tinggi dinamis berdasarkan konten kartu
    # Kartu kosong ~680px, kartu penuh (TP2+bandar+indikator) ~900px
    # Pakai 880 sebagai rata-rata + buffer 150px (extra untuk mobile)
    _card_h_avg = 880
    height_est  = rows_est * _card_h_avg + 150
    components.html(full_html, height=height_est, scrolling=False)

# ── SIGMA SHEETS — Google Sheets Persistent Storage ──────────────────────────
# FIX #6: Wrapped dalam try/except — jika modul gagal (credentials hilang,
# quota habis, network error), app tidak crash dan fallback ke stub functions.
try:
    from sigma_sheets import (
        sheets_available, save_broker_scan, load_broker_history,
        save_reko, load_reko_history, save_journal_entry, load_journal,
        update_journal_status, render_sheets_status, render_backup_button,
        render_history_table, log_backup,
    )
    _SHEETS_OK = True
except Exception as _sheets_import_err:
    _SHEETS_OK = False
    import warnings
    warnings.warn(f"[SIGMA] sigma_sheets tidak tersedia: {_sheets_import_err}")

    # ── Stub functions — app tetap jalan meski Sheets offline ──
    def sheets_available():           return False
    def save_broker_scan(*a, **k):    return None
    def load_broker_history(*a, **k): return {}
    def save_reko(*a, **k):           return None
    def load_reko_history(*a, **k):   return []
    def save_journal_entry(*a, **k):  return None
    def load_journal(*a, **k):        return []
    def update_journal_status(*a, **k): return None
    def render_sheets_status(*a, **k):  st.warning("⚠️ Google Sheets offline — data tidak tersimpan permanen.")
    def render_backup_button(*a, **k):  pass
    def render_history_table(*a, **k):  pass
    def log_backup(*a, **k):            return None
# ─────────────────────────────────────────────────────────────────────────────

# ── SIGMA HTML SANITIZER ──
def _sanitize_html_text(raw) -> str:
    """Hapus tag HTML yang bocor dari string teks sebelum dirender sebagai plain text.
    Bug#20 fix: hanya hapus tag HTML yang berasal dari template/render, bukan
    konten ketikan user (misal <BBCA> dalam pertanyaan teknis).
    Strategi: hapus HANYA tag yang merupakan tag HTML dikenal, bukan semua <...>.
    """
    import html as _html_mod
    if not isinstance(raw, str):
        return str(raw) if raw is not None else ""
    # Decode HTML entities dulu (&amp; → &, &lt; → <, dll)
    decoded = _html_mod.unescape(raw)
    # Hapus hanya tag HTML dikenal (div, span, p, br, strong, dll)
    # Biarkan <BBCA>, <ticker>, atau konten user yang kebetulan pakai < >
    _HTML_KNOWN = r'(?i)</?(?:div|span|p|br|strong|b|i|em|ul|ol|li|a|h[1-6]|table|tr|td|th|thead|tbody|style|script|meta|html|body|head|form|input|button|img|svg|path|g|section|article|header|footer|nav|aside|main)[^>]*>'
    cleaned = re.sub(_HTML_KNOWN, '', decoded)
    return cleaned.strip()

# ── SIGMA GEMINI RATE LIMIT MANAGER ──
# Menyimpan waktu cooldown per key-hash (dalam memory session)
_gemini_cooldown: dict = {}
_BACKOFF_BASE_SEC = 25      # detik cooldown awal setelah 429
_BACKOFF_MAX_SEC  = 180     # batas atas cooldown eksponensial
# ── SIGMA GROQ RATE LIMIT MANAGER ──
_groq_cooldown: dict = {}
_GROQ_BACKOFF_BASE_SEC = 30
_GROQ_BACKOFF_MAX_SEC  = 300

# ── SIGMA MIMO RATE LIMIT MANAGER ──
_mimo_cooldown: dict = {}
_MIMO_BACKOFF_BASE_SEC = 20
_MIMO_BACKOFF_MAX_SEC  = 240

def _mark_groq_key_ratelimited(key: str) -> None:
    """Tandai key Groq sebagai rate-limited dengan exponential backoff + jitter."""
    h = hashlib.md5(key.encode()).hexdigest()[:10]
    now = time.time()
    prev_until = _groq_cooldown.get(h, 0)
    if prev_until > now:
        wait = min((prev_until - now) * 2 + random.uniform(3, 10), _GROQ_BACKOFF_MAX_SEC)
    else:
        wait = _GROQ_BACKOFF_BASE_SEC + random.uniform(1, 15)
    _groq_cooldown[h] = now + wait

def _groq_key_available(key: str) -> bool:
    h = hashlib.md5(key.encode()).hexdigest()[:10]
    return time.time() >= _groq_cooldown.get(h, 0)

def _get_available_groq_keys(all_keys: list) -> list:
    available = [(n, k) for n, k in all_keys if _groq_key_available(k)]
    return available if available else all_keys

# ── SIGMA MIMO RATE LIMIT FUNCTIONS ──
def _mark_mimo_key_ratelimited(key: str) -> None:
    """Tandai MiMo key sebagai rate-limited dengan exponential backoff + jitter."""
    h = hashlib.md5(key.encode()).hexdigest()[:10]
    now = time.time()
    prev_until = _mimo_cooldown.get(h, 0)
    if prev_until > now:
        wait = min((prev_until - now) * 2 + random.uniform(3, 10), _MIMO_BACKOFF_MAX_SEC)
    else:
        wait = _MIMO_BACKOFF_BASE_SEC + random.uniform(1, 12)
    _mimo_cooldown[h] = now + wait

def _mimo_key_available(key: str) -> bool:
    h = hashlib.md5(key.encode()).hexdigest()[:10]
    return time.time() >= _mimo_cooldown.get(h, 0)

def _friendly_ratelimit_message() -> str:
    now = time.time()
    soonest = min(_groq_cooldown.values(), default=now)
    sisa = max(0, soonest - now)
    if sisa < 10: eta = "beberapa detik lagi"
    elif sisa < 60: eta = f"sekitar {int(sisa)} detik lagi"
    else: eta = f"sekitar {int(sisa // 60)} menit lagi"
    return (
        f"⏳ **SIGMA sedang ramai** — semua jalur AI sedang dalam antrian rate limit.\n\n"
        f"Estimasi tersedia kembali: **{eta}**.\n\nCoba kirim pesan lagi sebentar."
    )



def _mark_gemini_key_ratelimited(key: str) -> None:
    """Tandai key sebagai rate-limited dengan exponential backoff + random jitter."""
    h = hashlib.md5(key.encode()).hexdigest()[:10]
    now = time.time()
    prev_until = _gemini_cooldown.get(h, 0)
    if prev_until > now:
        # Masih dalam cooldown sebelumnya → double + jitter (eksponensial)
        remaining = prev_until - now
        wait = min(remaining * 2 + random.uniform(2, 8), _BACKOFF_MAX_SEC)
    else:
        # Pertama kali 429 → base + jitter
        wait = _BACKOFF_BASE_SEC + random.uniform(1, 10)
    _gemini_cooldown[h] = now + wait

def _gemini_key_available(key: str) -> bool:
    """Return True jika key tidak sedang dalam cooldown period."""
    h = hashlib.md5(key.encode()).hexdigest()[:10]
    return time.time() >= _gemini_cooldown.get(h, 0)

def _get_available_gemini_keys(all_keys: list) -> list:
    """Return key yang tidak sedang cooldown. Fallback ke semua key jika semua cooldown."""
    available = [k for k in all_keys if _gemini_key_available(k)]
    return available if available else all_keys

