# ─── MULTI-SOURCE DATA (yfinance → stooq → IDX API) ───
def _fetch_all_data(tickers):
    import threading
    result = {"prices": {}, "news": []}

    def fetch():
        # Layer 1: IDX API - sumber PALING AKURAT, langsung dari bursa
        for tk in tickers[:3]:
            try:
                import urllib.request, json as _j
                req = urllib.request.Request(
                    f"https://www.idx.co.id/umbraco/Surface/StockData/GetTradingInfoSS?code={tk}",
                    headers={"User-Agent":"Mozilla/5.0","Referer":"https://www.idx.co.id/"}
                )
                with urllib.request.urlopen(req, timeout=5) as r:
                    d = _j.loads(r.read())
                if d and d.get("LastPrice") and d["LastPrice"] > 0:
                    result["prices"][tk] = {
                        "price": d["LastPrice"],
                        "chg": d.get("ChangePercentage", 0),
                        "open": d.get("OpenPrice", 0),
                        "high": d.get("HighPrice", 0),
                        "low": d.get("LowPrice", 0),
                        "vol": d.get("Volume", 0),
                        "source": "IDX"
                    }
            except Exception: pass

        # Layer 2: Finnhub - reliable, adjusted (rotate KEY s/d KEY6)
        try:
            import urllib.request as _ufh, json as _jfh
            _fh_keys = _get_all_finnhub_keys() or [st.secrets.get("FINNHUB_KEY", "")]
            _fh_key = next((k for k in _fh_keys if k and len(k) > 10), "")
            if _fh_key:
                for tk in tickers[:3]:
                    if tk not in result["prices"]:
                        try:
                            _fh_url = f"https://finnhub.io/api/v1/quote?symbol={tk}.JK&token={_fh_key}"
                            _fh_req = _ufh.Request(_fh_url, headers={"User-Agent":"Mozilla/5.0"})
                            with _ufh.urlopen(_fh_req, timeout=5) as r:
                                _fh_d = _jfh.loads(r.read())
                            _fh_price = _fh_d.get("c", 0)  # current price
                            _fh_prev  = _fh_d.get("pc", 0) # previous close
                            if _fh_price and _fh_price > 0:
                                _fh_chg = ((_fh_price-_fh_prev) / _fh_prev * 100) if _fh_prev else 0
                                result["prices"][tk] = {
                                    "price": round(_fh_price, 0),
                                    "chg": round(_fh_chg, 2),
                                    "high": _fh_d.get("h", 0),
                                    "low": _fh_d.get("l", 0),
                                    "source": "Finnhub"
                                }
                        except Exception: pass
        except Exception: pass

        # Layer 3: FMP - financial data provider (rotate KEY s/d KEY6)
        try:
            import urllib.request as _ufmp, json as _jfmp
            _fmp_keys = _get_all_fmp_keys() or [st.secrets.get("FMP_KEY", "")]
            _fmp_key = next((k for k in _fmp_keys if k and len(k) > 10), "")
            if _fmp_key:
                for tk in tickers[:3]:
                    if tk not in result["prices"]:
                        try:
                            _fmp_url = f"https://financialmodelingprep.com/api/v3/quote/{tk}.JK?apikey={_fmp_key}"
                            _fmp_req = _ufmp.Request(_fmp_url, headers={"User-Agent":"Mozilla/5.0"})
                            with _ufmp.urlopen(_fmp_req, timeout=5) as r:
                                _fmp_d = _jfmp.loads(r.read())
                            if _fmp_d and isinstance(_fmp_d, list) and _fmp_d[0].get("price"):
                                _fmp_q = _fmp_d[0]
                                result["prices"][tk] = {
                                    "price": round(_fmp_q["price"], 0),
                                    "chg": round(_fmp_q.get("changesPercentage", 0), 2),
                                    "high": _fmp_q.get("dayHigh", 0),
                                    "low": _fmp_q.get("dayLow", 0),
                                    "vol": _fmp_q.get("volume", 0),
                                    "source": "FMP"
                                }
                        except Exception: pass
        except Exception: pass

        # Layer 4: Yahoo Finance query API - realtime, adjusted
        for tk in tickers[:3]:
            if tk not in result["prices"]:
                try:
                    import urllib.request, json as _j
                    _url = f"https://query1.finance.yahoo.com/v8/finance/chart/{tk}.JK?interval=1d&range=5d"
                    _req = urllib.request.Request(_url, headers={"User-Agent":"Mozilla/5.0"})
                    with urllib.request.urlopen(_req, timeout=5) as r:
                        _d = _j.loads(r.read())
                    _meta = _d["chart"]["result"][0]["meta"]
                    _price = _meta.get("regularMarketPrice") or _meta.get("previousClose")
                    _prev  = _meta.get("previousClose", _price)
                    if _price and _price > 0:
                        _chg = ((_price-_prev) / _prev * 100) if _prev else 0
                        result["prices"][tk] = {
                            "price": round(_price, 0),
                            "chg": round(_chg, 2),
                            "high": _meta.get("regularMarketDayHigh", 0),
                            "low": _meta.get("regularMarketDayLow", 0),
                            "vol": _meta.get("regularMarketVolume", 0),
                            "source": "Yahoo"
                        }
                except Exception: pass

        # Layer 5: yfinance - backup dengan auto_adjust + averageVolume
        try:
            import yfinance as yf
            for tk in tickers[:3]:
                try:
                    t = yf.Ticker(f"{tk}.JK")
                    info = t.info
                    # Selalu ambil averageVolume meski harga sudah ada dari layer sebelumnya
                    avg_vol = info.get("averageVolume") or info.get("averageDailyVolume10Day")
                    avg_vol3m = info.get("averageVolume3Month") or info.get("averageVolume")
                    if avg_vol and tk in result["prices"]:
                        result["prices"][tk]["avg_vol"] = avg_vol
                        result["prices"][tk]["avg_vol_src"] = "yfinance(3M)"
                    if avg_vol3m and tk in result["prices"] and not result["prices"][tk].get("avg_vol"):
                        result["prices"][tk]["avg_vol"] = avg_vol3m
                    # Kalau belum ada harga sama sekali, pakai yfinance
                    if tk not in result["prices"]:
                        h = t.history(period="5d", auto_adjust=True)
                        if not h.empty:
                            last = h.iloc[-1]
                            prev = h.iloc[-2] if len(h)>1 else last
                            chg = ((last["Close"]-prev["Close"])/prev["Close"]*100) if prev["Close"] else 0
                            result["prices"][tk] = {
                                "price": round(last["Close"],0),
                                "chg": round(chg,2),
                                "pe": info.get("trailingPE"),
                                "pbv": info.get("priceToBook"),
                                "eps": info.get("trailingEps"),
                                "roe": info.get("returnOnEquity"),
                                "avg_vol": avg_vol,
                                "avg_vol_src": "yfinance(3M)",
                                "source": "yfinance"
                            }
                except Exception as _yf_tk_err:  # FIX #4
                    _sigma_log_error("build_context_yf_ticker", _yf_tk_err, extra=tk)
        except Exception as _yf_err:  # FIX #4
            _sigma_log_error("build_context_yf_import", _yf_err)

        # Layer 6: stooq - backup terakhir
        try:
            import pandas_datareader as pdr
            from datetime import timedelta
            for tk in tickers[:3]:
                if tk not in result["prices"]:
                    try:
                        df = pdr.get_data_stooq(
                            f"{tk}.JK",
                            start=datetime.now()-timedelta(days=7),
                            end=datetime.now()
                        )
                        if not df.empty:
                            df = df.sort_index()
                            last = df.iloc[-1]
                            prev = df.iloc[-2] if len(df)>1 else last
                            chg = ((last["Close"]-prev["Close"])/prev["Close"]*100) if prev["Close"] else 0
                            result["prices"][tk] = {
                                "price": round(last["Close"],0),
                                "chg": round(chg,2),
                                "source": "stooq"
                            }
                    except Exception: pass
        except Exception: pass

        # Berita: Google News + CNBC ID + Kontan + Bisnis
        try:
            import feedparser
            seen = set()
            q = tickers[0] if tickers else "ihsg"
            sources = [
                ("Google", f"https://news.google.com/rss/search?q={requests.utils.quote(q+' saham IDX')}&hl=id&gl=ID&ceid=ID:id"),
                ("CNBC ID", "https://www.cnbcindonesia.com/rss"),
                ("Kontan", "https://rss.kontan.co.id/category/investasi"),
                ("Bisnis", "https://ekonomi.bisnis.com/rss"),
            ]
            mkt_kw = [q.lower(),"ihsg","saham","bursa","ekonomi","rupiah","pasar",
                      "inflasi","perang","global","emiten","investor"]
            for sn, su in sources:
                try:
                    feed = feedparser.parse(su)
                    cnt = 0
                    for e in feed.entries:
                        if cnt >= 2: break
                        title = e.title.strip()
                        key = title[:30].lower()
                        if key not in seen and (sn=="Google" or any(k in title.lower() for k in mkt_kw)):
                            seen.add(key)
                            result["news"].append(f"[{sn}] {title}")
                            cnt += 1
                except Exception: pass
        except Exception: pass

    th = threading.Thread(target=fetch, daemon=True)
    th.start()
    th.join(timeout=10)
    # Bug#11 fix: join() bisa return karena timeout, bukan karena thread selesai.
    # Thread fetch masih mungkin berjalan dan nulis ke result dict.
    # Aman di sini karena fetch() hanya append ke list result["news"],
    # tidak delete/overwrite key yang sudah ada (GIL protect single-key access).
    return result



# ═══════════════════════════════════════════════════════════════════════════════
# GOAPI.IO — Stock Market IDX
# Semua kemungkinan base URL dicoba secara berurutan (self-discovery)
# Hits=0 di dashboard berarti URL masih salah — kode ini probe otomatis
# ═══════════════════════════════════════════════════════════════════════════════

# Kandidat base URL — dicoba berurutan sampai ada yang respond bukan 404
_GOAPI_BASE_CANDIDATES = [
    "https://api.goapi.io/stock/idx",   # ← BENAR (dari dokumentasi resmi)
]

# Runtime-resolved base URL (diisi saat pertama kali sukses, atau oleh Test GoAPI)
GOAPI_BASE = "https://api.goapi.io/stock/idx"  # default, akan di-override jika ditemukan yang benar


def _goapi_headers():
    key = st.secrets.get("GoAPI_KEY", "")
    return {"X-API-KEY": key, "Accept": "application/json"}


def _goapi_available():
    """Cek apakah GoAPI key tersedia dan valid."""
    key = st.secrets.get("GoAPI_KEY", "")
    return bool(key and key.strip() and len(key.strip()) > 5)


def _goapi_resolve_base(force: bool = False) -> str:
    """
    Probe semua kandidat base URL dan return yang pertama kali berhasil
    (bukan 404 untuk endpoint /{symbol}/broker_summary).
    Hasil di-cache di session_state["_goapi_base_resolved"].
    """
    global GOAPI_BASE
    # Gunakan cache dulu
    if not force:
        cached = None
        try:
            cached = st.session_state.get("_goapi_base_resolved")
        except Exception:
            pass
        if cached:
            GOAPI_BASE = cached
            return cached

    from datetime import date as _d, timedelta as _td
    # Pakai tanggal yang paling mungkin ada datanya
    today = _d.today()
    test_date = None
    for delta in range(1, 8):
        cand = today - _td(days=delta)
        if cand.weekday() < 5:
            test_date = str(cand)
            break
    if not test_date:
        test_date = str(today - _td(days=1))

    key = st.secrets.get("GoAPI_KEY", "")
    headers = {"X-API-KEY": key, "Accept": "application/json"}

    for base in _GOAPI_BASE_CANDIDATES:
        try:
            r = requests.get(
                f"{base}/TLKM/broker_summary",
                params={"date": test_date, "investor": "ALL"},
                headers=headers, timeout=8)
            # 200/429 = URL valid (429 = rate limited, path benar)
            # FIX Bug#10: 401/403 = auth error, bukan bukti URL valid — skip
            if r.status_code in (401, 403):
                try: st.session_state["_goapi_auth_error"] = True
                except Exception: pass
                continue
            if r.status_code in (200, 429):
                GOAPI_BASE = base
                try:
                    st.session_state["_goapi_base_resolved"] = base
                    st.session_state.pop("_goapi_server_down", None)
                    st.session_state.pop("_goapi_auth_error", None)
                except Exception:
                    pass
                return base
            # 5xx Cloudflare/server down — URL benar tapi server tidak bisa dijangkau
            # Tetap set sebagai base yang valid agar error message jelas
            if r.status_code in (523, 522, 521, 520, 502, 503, 504):
                GOAPI_BASE = base
                try:
                    st.session_state["_goapi_base_resolved"] = base
                    st.session_state["_goapi_server_down"] = True
                except Exception:
                    pass
                return base
            # 404 = path tidak ada → coba berikutnya
        except Exception:
            continue
    # Tidak ada yang cocok — kembalikan default
    return GOAPI_BASE

@st.cache_data(ttl=90, show_spinner=False)
def goapi_get_price(ticker: str) -> dict:
    """Harga real-time satu saham dari GoAPI. Endpoint: /stock/idx/{symbol}
    Cache 90 detik — semua user dalam window ini pakai data yang sama."""
    _goapi_throttle()
    try:
        r = requests.get(f"{GOAPI_BASE}/{ticker}", headers=_goapi_headers(), timeout=10)
        if r.status_code != 200:
            return {}
        data = r.json()
        # Response: {"status":"success","data":{"results":[{...}]}} atau {"data":{...}}
        if isinstance(data, dict):
            inner = data.get("data", data)
            if isinstance(inner, dict):
                results = inner.get("results", [])
                if results and isinstance(results, list):
                    return results[0]
                return inner
            elif isinstance(inner, list) and inner:
                return inner[0]
        return data
    except Exception:
        return {}

@st.cache_data(ttl=90, show_spinner=False)
def goapi_get_prices(tickers: tuple) -> dict:
    """Harga real-time multiple ticker. Endpoint: /stock/idx/prices?symbols=A,B,C
    PATCH: parameter list→tuple agar cacheable. Panggil dengan tuple(sorted(list)).
    Cache 90 detik — semua user dalam window ini pakai data yang sama."""
    _goapi_throttle()
    try:
        symbols = ",".join(tickers)
        r = requests.get(f"{GOAPI_BASE}/prices", params={"symbols": symbols},
                         headers=_goapi_headers(), timeout=12)
        if r.status_code != 200:
            return {}
        data = r.json()
        # Response: {"status":"success","data":{"results":[{symbol,close,...}]}}
        # Return dict keyed by symbol for easy lookup
        if isinstance(data, dict):
            inner = data.get("data", {})
            results = inner.get("results", []) if isinstance(inner, dict) else []
            return {row["symbol"]: row for row in results if isinstance(row, dict) and "symbol" in row}
        return {}
    except Exception:
        return {}

def _last_trading_date(max_lookback: int = 7) -> str:
    """
    Cari hari bursa terakhir (T-1 atau lebih).
    Skip Sabtu (5) dan Minggu (6). Fallback sampai max_lookback hari.
    """
    from datetime import date as _d, timedelta as _td
    today = _d.today()
    for delta in range(1, max_lookback + 1):
        candidate = today - _td(days=delta)
        if candidate.weekday() < 5:
            return str(candidate)
    return str(today - _td(days=1))


def _trading_date_candidates(date_str: str = None, max_lookback: int = 5) -> list:
    """
    Buat list kandidat tanggal hari bursa untuk dicoba secara berurutan (dari terbaru ke terlama).
    Jika date_str diberikan, mulai dari situ lalu mundur.
    Jika tidak, mulai dari T-1 lalu mundur sampai max_lookback hari bursa.
    Digunakan untuk auto-retry GoAPI broker-summary.
    """
    from datetime import date as _d, timedelta as _td, datetime as _dtt
    if date_str:
        try:
            start = _dtt.strptime(date_str, "%Y-%m-%d").date()
        except Exception:
            start = _d.today() - _td(days=1)
    else:
        start = _d.today() - _td(days=1)
    candidates = []
    delta = 0
    while len(candidates) < max_lookback:
        cand = start - _td(days=delta)
        if cand.weekday() < 5:
            candidates.append(str(cand))
        delta += 1
        if delta > 30:
            break
    return candidates



# ── GoAPI Request Throttler (Thread-Safe) ────────────────────────────────────
# Batasi request GoAPI: min 1.5 detik antar request untuk hindari 429
# Thread-safe: gunakan Lock agar multi-thread tidak bypass throttler
import threading as _threading_goapi
_GOAPI_MIN_INTERVAL = 1.5   # detik antar request (naik dari 1.2 → lebih aman)
_goapi_last_req_time: float = 0.0
_goapi_throttle_lock = _threading_goapi.Lock()

def _goapi_throttle():
    """Tunggu sebelum request GoAPI agar tidak kena rate limit.
    Thread-safe: satu request keluar tiap min 1.5 detik meski dari banyak thread.
    """
    global _goapi_last_req_time
    with _goapi_throttle_lock:
        elapsed = time.time() - _goapi_last_req_time
        wait    = _GOAPI_MIN_INTERVAL - elapsed
        if wait > 0:
            time.sleep(wait)
        _goapi_last_req_time = time.time()
# ─────────────────────────────────────────────────────────────────────────────

def goapi_get_broker_summary(ticker: str, date_str: str = None) -> list:
    """
    Broker summary per saham dari GoAPI.
    Endpoint resmi: GET https://api.goapi.io/stock/idx/{symbol}/broker_summary
    Params: date (YYYY-MM-DD), investor (LOCAL|FOREIGN|ALL)
    Return: list of broker rows normalized untuk SIGMA parser.

    Auto-retry: jika 404/kosong, mundur ke T-2, T-3 dst (maks 5 hari bursa).
    """
    _goapi_resolve_base()
    _goapi_throttle()   # rate-limit guard: min 1.2s antar request
    # Jika date_str sudah spesifik (dari _goapi_resolve_latest_date), lookback=1 saja (hemat quota)
    # Jika tidak ada date, lookback=3 (lebih konservatif dari 10 sebelumnya)
    _max_lb = 1 if date_str else 3
    candidates = _trading_date_candidates(date_str, max_lookback=_max_lb)
    last_err = f"Semua tanggal dicoba kosong: {candidates}"
    _debug_log = []  # collect per-date results for better error reporting
    for _try_date in candidates:
        try:
            # URL baru: /{symbol}/broker_summary  (bukan /broker-summary?symbol=)
            r = requests.get(
                f"{GOAPI_BASE}/{ticker}/broker_summary",
                params={"date": _try_date, "investor": "ALL"},
                headers=_goapi_headers(), timeout=20)
            if r.status_code == 429:
                last_err = f"HTTP 429 untuk {ticker} ({_try_date}) — throttled (bukan quota habis, coba lagi sebentar)"
                try:
                    import streamlit as _st_g
                    _st_g.session_state["_goapi_last_error"] = last_err
                except Exception:
                    pass
                # ── Retry dengan exponential backoff (max 2x, mulai 5 detik) ──
                # Start 5 detik bukan 2 detik — GoAPI perlu jeda cukup setelah throttle
                _retry_wait = 5
                for _retry in range(2):
                    time.sleep(_retry_wait + random.uniform(0.5, 1.5))
                    try:
                        r2 = requests.get(
                            f"{GOAPI_BASE}/{ticker}/broker_summary",
                            params={"date": _try_date, "investor": "ALL"},
                            headers=_goapi_headers(), timeout=20)
                        if r2.status_code == 200:
                            r = r2
                            break
                        elif r2.status_code == 429:
                            _retry_wait = min(_retry_wait * 2, 16)
                            continue
                        else:
                            break
                    except Exception:
                        _retry_wait = min(_retry_wait * 2, 16)
                        continue
                else:
                    # Semua retry gagal → return cached atau kosong
                    _cache_key = f"_brosum_{ticker}"
                    _cached = st.session_state.get(_cache_key)
                    if _cached:
                        return _cached
                    return []
                if r.status_code != 200:
                    _cache_key = f"_brosum_{ticker}"
                    _cached = st.session_state.get(_cache_key)
                    if _cached:
                        return _cached
                    return []
            if r.status_code in (523, 522, 521, 520, 502, 503, 504):
                # Cloudflare/origin unreachable — server GoAPI sedang down
                # Tidak ada gunanya retry tanggal lain, langsung stop
                last_err = (
                    f"GoAPI server unreachable (HTTP {r.status_code}) — "
                    f"Cloudflare tidak bisa menjangkau origin GoAPI. "
                    f"Coba lagi dalam beberapa menit."
                )
                try:
                    import streamlit as _st_g
                    _st_g.session_state["_goapi_last_error"] = last_err
                    _st_g.session_state["_goapi_server_down"] = True
                except Exception:
                    pass
                return []
            if r.status_code == 404:
                last_err = f"HTTP 404 untuk {ticker} ({_try_date})"
                continue
            if r.status_code != 200:
                last_err = f"HTTP {r.status_code} untuk {ticker} ({_try_date})"
                try:
                    _eb = r.json()
                    last_err += f" — {_eb.get('message', _eb.get('error', r.text[:80]))}"
                except Exception:
                    last_err += f" — {r.text[:80]}"
                continue
            # HTTP 200
            data = r.json()
            # Response format: {"status":"success","data":{"results":[...]}}
            if isinstance(data, dict):
                _status = str(data.get("status", "success")).lower()
                if _status in ("error", "fail", "failed", "0", "false"):
                    last_err = f"{ticker} ({_try_date}): {data.get('message', str(data)[:80])}"
                    continue
                # Coba semua kemungkinan key untuk rows (fixed operator precedence)
                _inner = data.get("data", {})
                if isinstance(_inner, dict):
                    rows = (_inner.get("results") or
                            _inner.get("broker_summary") or
                            _inner.get("brokerSummary") or
                            data.get("results") or
                            data.get("brokerSummary") or
                            data.get("broker_summary") or [])
                elif isinstance(_inner, list):
                    rows = _inner
                else:
                    rows = (data.get("results") or
                            data.get("brokerSummary") or
                            data.get("broker_summary") or [])
                if isinstance(rows, dict):
                    rows = list(rows.values())
            elif isinstance(data, list):
                rows = data
            else:
                rows = []

            if not rows:
                last_err = f"{ticker} ({_try_date}): HTTP 200 tapi data kosong"
                _debug_log.append(f"{_try_date}:EMPTY")
                continue

            # Normalize — response GoAPI baru punya field berbeda dari versi lama
            normalized = []
            for row in rows:
                if not isinstance(row, dict):
                    continue
                # Format baru: {"broker":{"code":"XL","name":"..."},"side":"BUY","lot":87051,...}
                broker_obj = row.get("broker", {})
                broker_code = str(row.get("code", broker_obj.get("code",
                              row.get("broker_code", row.get("brokerCode",
                              row.get("BrokerID", "?"))))))
                broker_name = row.get("name", broker_obj.get("name",
                              row.get("broker_name", row.get("BrokerName", ""))))

                side     = str(row.get("side", "")).upper()  # "BUY" atau "SELL"
                lot      = float(row.get("lot", row.get("buy_lot", row.get("sell_lot", 0))) or 0)
                value    = float(row.get("value", row.get("buy_value", row.get("sell_value", 0))) or 0)
                avg      = float(row.get("avg", row.get("avg_buy", row.get("avg_sell", 0))) or 0)
                investor = row.get("investor", "LOCAL")

                # Konversi format baru (per-side per-row) ke format lama (buy+sell per broker)
                # Format lama yang dipakai SIGMA: BuyVolume, SellVolume, BuyValue, SellValue, AvgBuy, AvgSell
                if side == "BUY":
                    normalized.append({
                        "BrokerID":    broker_code,
                        "BrokerName":  broker_name,
                        "BuyVolume":   lot,
                        "SellVolume":  0.0,
                        "BuyValue":    value,
                        "SellValue":   0.0,
                        "AvgBuy":      avg,
                        "AvgSell":     0.0,
                        "InvestorBuy": investor,
                        "InvestorSell": None,
                        "_source":     "GoAPI",
                        "_date":       _try_date,
                    })
                elif side == "SELL":
                    normalized.append({
                        "BrokerID":    broker_code,
                        "BrokerName":  broker_name,
                        "BuyVolume":   0.0,
                        "SellVolume":  lot,
                        "BuyValue":    0.0,
                        "SellValue":   value,
                        "AvgBuy":      0.0,
                        "AvgSell":     avg,
                        "InvestorBuy": None,
                        "InvestorSell": investor,
                        "_source":     "GoAPI",
                        "_date":       _try_date,
                    })
                else:
                    # Format lama (fallback): row sudah punya BuyVolume/SellVolume
                    buy_lot  = float(row.get("buy_lot",   row.get("buyLot",   row.get("BuyVolume",  0))) or 0)
                    sell_lot = float(row.get("sell_lot",  row.get("sellLot",  row.get("SellVolume", 0))) or 0)
                    normalized.append({
                        "BrokerID":    broker_code,
                        "BrokerName":  broker_name,
                        "BuyVolume":   buy_lot,
                        "SellVolume":  sell_lot,
                        "BuyValue":    float(row.get("buy_value",  row.get("BuyValue",  0)) or 0),
                        "SellValue":   float(row.get("sell_value", row.get("SellValue", 0)) or 0),
                        "AvgBuy":      float(row.get("avg_buy",    row.get("AvgBuy",    0)) or 0),
                        "AvgSell":     float(row.get("avg_sell",   row.get("AvgSell",   0)) or 0),
                        "InvestorBuy":  row.get("investor_buy",  row.get("InvestorBuy",  investor)),
                        "InvestorSell": row.get("investor_sell", row.get("InvestorSell", None)),
                        "_source":     "GoAPI",
                        "_date":       _try_date,
                    })
            if not normalized:
                last_err = f"{ticker} ({_try_date}): rows ada tapi semua tidak valid"
                continue
            # ── Cache hasil sukses ke session_state ──
            try:
                st.session_state[f"_brosum_{ticker}"] = normalized
                st.session_state[f"_brosum_{ticker}_date"] = _try_date
            except Exception:
                pass
            return normalized
        except Exception as _ge:
            last_err = f"Exception {ticker} ({_try_date}): {type(_ge).__name__}: {str(_ge)[:80]}"
            continue

    # Semua kandidat gagal — coba kembalikan cache terakhir jika ada
    _cache_key = f"_brosum_{ticker}"
    _cached_result = st.session_state.get(_cache_key)
    if _cached_result:
        _cached_date = st.session_state.get(f"{_cache_key}_date", "?")
        last_err = f"{last_err} | Menampilkan data cache ({_cached_date})"
        try:
            st.session_state["_goapi_last_error"] = last_err
        except Exception:
            pass
        return _cached_result
    last_err = f"{last_err} | debug: {'; '.join(_debug_log) if _debug_log else 'no attempts logged'}"
    try:
        import streamlit as _st_g
        _st_g.session_state["_goapi_last_error"] = last_err
    except Exception:
        pass
    return []

def _goapi_resolve_latest_date(test_ticker: str = "BBCA") -> str:
    """
    Temukan tanggal trading terbaru yang punya data GoAPI broker summary.
    Gunakan 1 test request ke ticker liquid (BBCA/BBRI) — hemat quota.
    Return: date string "YYYY-MM-DD" atau "" jika tidak ditemukan.
    Hasil di-cache di session_state['_goapi_resolved_date'] per hari.
    """
    import streamlit as _st_r
    from datetime import date as _dr, timedelta as _tdr
    _today = _dr.today().isoformat()
    _cache_key = f"_goapi_resolved_date_{_today}"
    if _st_r.session_state.get(_cache_key):
        return _st_r.session_state[_cache_key]
    candidates = _trading_date_candidates(max_lookback=5)
    for _cdate in candidates:
        try:
            r = requests.get(
                f"{GOAPI_BASE}/{test_ticker}/broker_summary",
                params={"date": _cdate, "investor": "ALL"},
                headers=_goapi_headers(), timeout=15)
            if r.status_code == 429:
                _st_r.session_state["_goapi_last_error"] = f"HTTP 429 throttled — bukan quota habis, tunggu sebentar"
                # Tunggu lalu retry sekali sebelum menyerah
                time.sleep(15 + random.uniform(1, 5))
                try:
                    r2 = requests.get(
                        f"{GOAPI_BASE}/{test_ticker}/broker_summary",
                        params={"date": _cdate, "investor": "ALL"},
                        headers=_goapi_headers(), timeout=15)
                    if r2.status_code == 200:
                        r = r2
                    else:
                        return ""
                except Exception:
                    return ""
            if r.status_code == 200:
                data = r.json()
                _inner = data.get("data", {}) if isinstance(data, dict) else {}
                rows = (_inner.get("results") or _inner.get("broker_summary") or
                        _inner.get("brokerSummary") or data.get("results") or []) if isinstance(_inner, dict) else _inner
                if rows:
                    _st_r.session_state[_cache_key] = _cdate
                    return _cdate
        except Exception:
            continue
    return ""


def goapi_get_historical(ticker: str, date_from: str, date_to: str) -> list:
    """OHLCV historis dari GoAPI — max range 1 tahun. Endpoint: /{symbol}/historical"""
    try:
        r = requests.get(f"{GOAPI_BASE}/{ticker}/historical",
                         params={"from": date_from, "to": date_to},
                         headers=_goapi_headers(), timeout=20)
        if r.status_code != 200:
            return []
        data = r.json()
        # Response: {"data":{"results":[{...}]}}
        if isinstance(data, dict):
            inner = data.get("data", data)
            if isinstance(inner, dict):
                results = inner.get("results", inner.get("data", []))
                return results if isinstance(results, list) else []
            elif isinstance(inner, list):
                return inner
        if isinstance(data, dict):
            return data.get("data", data.get("historical", []))
        return data if isinstance(data, list) else []
    except Exception:
        return []

