# ── AUTO-SYNC: Merge live suspend data dari IDX ke dict global ─────────────────
# Fungsi ini di-call sekali saat startup (cache 6 jam) untuk menangkap
# suspend/unsuspend terbaru tanpa harus edit kode secara manual.
import functools as _functools

@st.cache_data(ttl=21600, show_spinner=False)  # cache 6 jam
def _fetch_live_suspended_tickers() -> dict:
    """
    Coba ambil daftar suspend terkini dari IDX RDIS API.
    Return dict {ticker: keterangan} atau {} kalau gagal.
    Tidak pernah raise — fallback ke dict kosong jika error.
    """
    live = {}
    try:
        import requests as _req
        # IDX RDIS — endpoint JSON suspend aktif
        _headers = {"User-Agent": "Mozilla/5.0 (compatible; SIGMA/2.0)"}
        _url = "https://www.idx.co.id/primary/TradingHalt/GetListHalt?start=0&length=200&column=&dir=&type=1"
        _r = _req.get(_url, headers=_headers, timeout=8)
        if _r.status_code == 200:
            _data = _r.json()
            for _item in _data.get("data", []):
                _code = (_item.get("StockCode") or "").strip().upper()
                _name = _item.get("StockName") or _item.get("Efek") or _code
                _date = _item.get("HaltDate") or _item.get("SuspendDate") or ""
                if _code:
                    live[_code] = f"SUSPEND (IDX Live) - {_name}, sejak {_date}"
    except Exception:
        pass
    # Fallback 2: coba endpoint alternatif
    if not live:
        try:
            import requests as _req
            _url2 = "https://www.idx.co.id/primary/TradingHalt/GetListHalt?start=0&length=200&column=&dir=&type=2"
            _r2 = _req.get(_url2, headers={"User-Agent": "Mozilla/5.0"}, timeout=8)
            if _r2.status_code == 200:
                for _item in _r2.json().get("data", []):
                    _code = (_item.get("StockCode") or "").strip().upper()
                    _name = _item.get("StockName") or _code
                    _date = _item.get("HaltDate") or ""
                    if _code:
                        live[_code] = f"SUSPEND (IDX Live) - {_name}, sejak {_date}"
        except Exception:
            pass
    return live

def _get_merged_suspended_tickers() -> dict:
    """
    Gabungkan hardcoded list + live IDX data.
    Live data menang kalau ada ticker baru.
    Hardcoded menang kalau live kosong (fallback aman).
    """
    merged = dict(IDX_SUSPENDED_TICKERS_GLOBAL)
    try:
        live = _fetch_live_suspended_tickers()
        if live:
            merged.update(live)  # live ticker override / tambah ke list
    except Exception:
        pass
    return merged

# Gunakan versi merged di seluruh app
_SUSPENDED_MERGED = _get_merged_suspended_tickers



def _validate_price_corporate_action(ticker, price):
    """
    Validasi harga terhadap database corporate action.
    Return: (is_valid, warning_message)
   -is_valid=False → harga terindikasi pre-split/pre-reverse, jangan gunakan
   -warning_message → string peringatan untuk disertakan di prompt AI
    """
    if not price or price <= 0:
        return True, ""

    ticker = ticker.upper()

    # Cek suspend — gunakan merged (hardcoded + live IDX)
    _susp_db = _SUSPENDED_MERGED()
    if ticker in _susp_db:
        return False, (
            f"⛔ PERHATIAN KRITIS: {ticker} berstatus {_susp_db[ticker]}. "
            f"Saham ini TIDAK DAPAT diperdagangkan. DILARANG membuat trade plan atau rekomendasi beli."
        )

    # Cek corporate action
    ca = IDX_CORPORATE_ACTIONS.get(ticker)
    if not ca:
        return True, ""

    pre_lo, pre_hi = ca["pre_range"]
    post_lo, post_hi = ca["post_range"]

    if ca["type"] == "split":
        post_lo, post_hi = ca["post_range"]
        # Harga terindikasi pre-split HANYA jika jelas masuk range pre-split
        # DAN jauh melampaui organic ceiling post-split (kenaikan alami jangka panjang)
        # Toleransi 10x post_hi untuk mengakomodasi kenaikan organik multi-tahun
        organic_ceiling = post_hi * 10
        if price >= pre_lo * 0.85 and price > organic_ceiling:
            return False, (
                f"⚠️ PERINGATAN CORPORATE ACTION [{ticker}]: "
                f"Harga Rp{price:,.0f} terindikasi DATA PRE-SPLIT. "
                f"{ticker} melakukan stock split {ca['ratio']} pada {ca['date']}. "
                f"{ca['note']} "
                f"GUNAKAN harga post-split dari sumber live (IDX/yfinance adjusted). "
                f"JANGAN gunakan harga Rp{price:,.0f} ini untuk analisa."
            )
    elif ca["type"] == "reverse":
        # Harga terlalu rendah → kemungkinan data pre-reverse
        if price <= pre_hi * 1.3:
            return False, (
                f"⚠️ PERINGATAN CORPORATE ACTION [{ticker}]: "
                f"Harga Rp{price:,.0f} terindikasi DATA PRE-REVERSE SPLIT. "
                f"{ticker} melakukan reverse split {ca['ratio']} pada {ca['date']}. "
                f"{ca['note']} "
                f"GUNAKAN harga post-reverse dari sumber live."
            )

    return True, ""

def build_fundamental_from_text(prompt):
    ticker = detect_ticker_from_prompt(prompt)
    if not ticker: return ""
    import threading
    result = [""]
    
    def fetch():
        try:
            multi = fetch_fundamental_with_cache(ticker)
            current_year = 2026 # Force context ke 2026

            price_live = multi.get("price")

            # ── VALIDASI CORPORATE ACTION ──
            _ca_valid, _ca_warning = _validate_price_corporate_action(ticker, price_live)
            _ca_info = IDX_CORPORATE_ACTIONS.get(ticker.upper(), {})
            _suspend_warning = _SUSPENDED_MERGED().get(ticker.upper(), "")

            is_bank = is_bank_sector(ticker)
            sektor = "Perbankan" if is_bank else "Non-Perbankan"

            lines = [
                f"=== STATUS ANALISA: PRIORITAS UTAMA {current_year} ===",
                f"🚨 FOKUS UTAMA: Data Terbaru 2026 / TTM (Trailing Twelve Months).",
                f"📊 KONTEKS PEMBANDING: Gunakan data 2024-2025 untuk melihat tren (YoY/CAGR) dan mengisi data jika angka 2026 belum rilis sepenuhnya.",
                f"==========================================\n",
                f"=== DATA FUNDAMENTAL {ticker} ({sektor}) ==="
            ]

            # Inject suspend warning jika ada
            if _suspend_warning:
                lines.append(f"\n⛔ STATUS SUSPEND: {_suspend_warning}")
                lines.append(f"⛔ SIGMA WAJIB mencantumkan status SUSPEND ini di bagian paling atas output analisa.\n")

            # Inject corporate action info jika ada
            if _ca_info:
                lines.append(f"\n📋 CORPORATE ACTION {ticker}:")
                lines.append(f"   Jenis   : {_ca_info.get('type','').upper()} {_ca_info.get('ratio','')}")
                lines.append(f"   Tanggal : {_ca_info.get('date','')}")
                lines.append(f"   Catatan : {_ca_info.get('note','')}")

            # Inject price warning jika tidak valid
            if not _ca_valid and _ca_warning:
                lines.append(f"\n{_ca_warning}")
                lines.append(f"⚠️ SIGMA WAJIB: Notifikasi user tentang corporate action ini di output analisa.\n")
            elif price_live:
                lines.append(f"💹 Harga Saham Saat Ini : Rp{price_live:,.0f}")
            
            # Menampilkan Data 2026 dan Pembanding
            eps_2026 = multi.get("eps") # Asumsi TTM/2026
            eps_2025 = multi.get("eps_last_year") # Data pembanding
            
            if eps_2026:
                lines.append(f"EPS TTM (2026) : Rp{eps_2026:,.0f}")
                if eps_2025:
                    growth = ((eps_2026-eps_2025) / eps_2025) * 100
                    lines.append(f"Growth EPS vs 2025 : {growth:+.2f}%")
            
            # Valuasi Tetap Wajib Ada
            pe = multi.get("pe")
            pbv = multi.get("pbv")
            if pe: lines.append(f"PER (Current 2026) : {pe:.2f}×")
            if pbv: lines.append(f"PBV (Current 2026) : {pbv:.2f}×")
            
            if multi.get("roe"): lines.append(f"ROE (Latest) : {multi['roe']*100:.2f}%")
            if multi.get("div_yield"): lines.append(f"Dividend Yield : {multi['div_yield']*100:.2f}%")

            result[0] = "\n".join(lines)
        except Exception:
            result[0] = f"Gunakan knowledge 2026 sebagai prioritas untuk {ticker}, bandingkan dengan tren 2024-2025."
            
    th = threading.Thread(target=fetch, daemon=True)
    th.start()
    th.join(timeout=12)
    return result[0]

