# [removed duplicate import] import streamlit as st
# [removed duplicate import] import os
# [removed duplicate import] import hashlib
# [removed duplicate import] import bcrypt
# [removed duplicate import] import json

st.set_page_config(
    page_title="KIPM SIGMA",
    layout="wide",
    initial_sidebar_state="expanded"
)

DATA_DIR = os.path.join(os.path.expanduser("~"), ".sigma_data")
os.makedirs(DATA_DIR, exist_ok=True)

# =========================================================
# GOOGLE SHEETS PERSISTENT STORAGE — SIGMA_DATABASE
# =========================================================
def _ukey(email): return hashlib.md5(email.encode()).hexdigest()

# ═══════════════════════════════════════════════════════════════
# SIGMA DATABASE — Google Sheets Persistent Storage
# Sheet: SIGMA_DATABASE → worksheet "users" (1 row per user)
# Format: key=email_hash, value=JSON blob semua data user
# ═══════════════════════════════════════════════════════════════

# In-memory cache: worksheet object + row index
_db_ws_cache   = {}   # {sheet_name: worksheet_object}
_db_row_index  = {}   # {sheet_name: {key: row_number}}
_db_data_cache = {}   # {sheet_name: {key: value}}
_db_cache_ts   = {}   # {sheet_name: float timestamp}
_CACHE_TTL     = 60   # detik sebelum re-fetch dari Sheets

def _get_gspread_client():
    """Return authorized gspread client. Cache di session_state."""
    try:
        import gspread
        from google.oauth2.service_account import Credentials
        creds_dict = dict(st.secrets["gsheets_credentials"])
        scopes = [
            "https://www.googleapis.com/auth/spreadsheets",
            "https://www.googleapis.com/auth/drive",
        ]
        creds = Credentials.from_service_account_info(creds_dict, scopes=scopes)
        return gspread.authorize(creds)
    except Exception as _e:
        return None

def _get_db_sheet(sheet_name: str):
    """Return worksheet object. Cache in-process."""
    if sheet_name in _db_ws_cache:
        return _db_ws_cache[sheet_name]
    gc = _get_gspread_client()
    if gc is None:
        return None
    try:
        import gspread
        sid = st.secrets["gsheets"]["spreadsheet_database"]
        wb  = gc.open_by_key(sid)
        try:
            ws = wb.worksheet(sheet_name)
        except gspread.exceptions.WorksheetNotFound:
            ws = wb.add_worksheet(title=sheet_name, rows=2000, cols=3)
            ws.append_row(["key", "value", "updated_at"])
        _db_ws_cache[sheet_name] = ws
        return ws
    except Exception:
        return None

def _db_load_sheet(sheet_name: str) -> dict:
    """Fetch seluruh sheet → dict {key: parsed_value}. Dengan TTL cache."""
    now = time.time()
    if sheet_name in _db_data_cache and (now - _db_cache_ts.get(sheet_name, 0)) < _CACHE_TTL:
        return _db_data_cache[sheet_name]
    ws = _get_db_sheet(sheet_name)
    if ws is None:
        return _db_data_cache.get(sheet_name, {})
    try:
        all_vals = ws.get_all_values()   # lebih cepat dari get_all_records
        result   = {}
        row_idx  = {}
        for i, row in enumerate(all_vals):
            if i == 0: continue          # skip header
            if not row or not row[0].strip(): continue
            k = row[0].strip()
            v = row[1].strip() if len(row) > 1 else ""
            try:    result[k] = json.loads(v)
            except: result[k] = v
            row_idx[k] = i + 1          # 1-indexed row number di Sheets
        _db_data_cache[sheet_name] = result
        _db_row_index[sheet_name]  = row_idx
        _db_cache_ts[sheet_name]   = now
        return result
    except Exception:
        return _db_data_cache.get(sheet_name, {})

def _db_read_all(sheet_name: str) -> dict:
    """Public alias untuk _db_load_sheet."""
    return _db_load_sheet(sheet_name)

def _db_write(sheet_name: str, key: str, value) -> bool:
    """Tulis key-value ke worksheet (upsert). Return True jika berhasil."""
    ws = _get_db_sheet(sheet_name)
    # Fallback lokal kalau Sheets tidak available
    if ws is None:
        try:
            with open(os.path.join(DATA_DIR, f"fb_{sheet_name}_{key}.json"), "w") as _f:
                json.dump(value, _f, ensure_ascii=False)
        except Exception: pass
        return False
    try:
        value_str = json.dumps(value, ensure_ascii=False)
        now_str   = _wib_now().strftime("%Y-%m-%d %H:%M:%S")

        # Pastikan data cache ter-load supaya row_index akurat
        _db_load_sheet(sheet_name)

        row_idx = _db_row_index.get(sheet_name, {}).get(key)
        if row_idx:
            # Update row yang sudah ada (2 cell sekaligus)
            ws.update(f"B{row_idx}:C{row_idx}", [[value_str, now_str]])
        else:
            # Tambah row baru
            ws.append_row([key, value_str, now_str], value_input_option="RAW")
            # Update index cache
            if sheet_name not in _db_row_index:
                _db_row_index[sheet_name] = {}
            # Row baru ada di akhir — invalidate cache agar re-fetch
            _db_cache_ts[sheet_name] = 0

        # Update in-memory cache
        if sheet_name not in _db_data_cache:
            _db_data_cache[sheet_name] = {}
        _db_data_cache[sheet_name][key] = value

        # Tulis fallback lokal juga (double-safety)
        try:
            with open(os.path.join(DATA_DIR, f"fb_{sheet_name}_{key}.json"), "w") as _f:
                json.dump(value, _f, ensure_ascii=False)
        except Exception: pass
        return True
    except Exception as _e:
        # Fallback lokal
        try:
            with open(os.path.join(DATA_DIR, f"fb_{sheet_name}_{key}.json"), "w") as _f:
                json.dump(value, _f, ensure_ascii=False)
        except Exception: pass
        return False

# ── Public API: save_user / load_user (PER-FIELD STORAGE) ──
# Setiap field kritis disimpan sebagai row terpisah di sheet 'user_data'
# Format key: "{email_hash}:{field_name}"
# Ini menghindari race condition overwrite blob JSON besar

# Field-field yang disimpan per-row (tidak boleh overwrite satu sama lain)
_PERFIELD_KEYS = [
    "auto_plan_history_bsjp", "auto_plan_history_daily", "auto_plan_history_weekly",
    "tr_records", "brosum_history", "sigma_bs30_screened", "sigma_bs30_ts",
    "sigma_bs30_history", "brosum_hist_use_key", "brosum_hist_use_data",
    "brosum_hist_use_date",
    "fs_results", "fs_ts", "fs_sektor",  # Fundamental Screener
    "alpha_insight_last_key", "alpha_insight_last_data", "alpha_insight_last_ticker",  # Alpha Insight
    "sigma_track_record",
]
# Field-field session (disimpan satu blob di sheet 'users' — boleh overwrite)
_SESSION_KEYS = [
    "theme", "sessions", "active_id", "current_view", "selected_system",
    "reco_daily_result", "reco_daily_ts", "reco_weekly_result", "reco_weekly_ts",
    "reco_bsjp_result", "reco_bsjp_ts", "mb_daily_content", "mb_daily_timestamp",
    "mb_weekly_content", "mb_weekly_timestamp", "ec_ai_result", "ec_ai_event",
    "ec_ai_actual", "ec_ai_beat_miss", "ec_ai_model", "ec_ai_timestamp",
    "alpha_insight_last_key", "alpha_insight_last_data", "alpha_insight_last_ticker",
]

def _cleanup_session_state_bloat():
    """
    Bersihkan session state dari data yang terlalu besar atau terlalu lama.
    Dipanggil sekali saat login untuk mencegah memory bloat di sesi panjang.
    Batas:
      - brosum_history       → max 7 hari
      - auto_plan_history_*  → max 30 entri
      - sigma_bs30_history   → max 14 entri
      - tr_records           → max 200 entri
      - sigma_insight_*      → max 10 ticker (FIX B7)
      - _alpha_chart_*       → max 10 ticker (FIX B7)
      - _zone_cache_*        → max 10 ticker (FIX B7)
    """
    import sys

    # ── Batasi brosum_history: max 7 hari ──
    _bh = st.session_state.get("brosum_history", {})
    if isinstance(_bh, dict) and len(_bh) > 7:
        _sorted_keys = sorted(_bh.keys(), reverse=True)
        st.session_state["brosum_history"] = {k: _bh[k] for k in _sorted_keys[:7]}

    # ── Batasi auto_plan_history: max 30 entri per type ──
    for _pk in ["auto_plan_history_daily", "auto_plan_history_weekly", "auto_plan_history_bsjp"]:
        _ph = st.session_state.get(_pk, {})
        if isinstance(_ph, dict) and len(_ph) > 30:
            _sorted_plan_keys = sorted(_ph.keys(), reverse=True)
            st.session_state[_pk] = {k: _ph[k] for k in _sorted_plan_keys[:30]}

    # ── Batasi sigma_bs30_history: max 14 entri ──
    _sh = st.session_state.get("sigma_bs30_history", {})
    if isinstance(_sh, dict) and len(_sh) > 14:
        _sorted_sh = sorted(_sh.keys(), reverse=True)
        st.session_state["sigma_bs30_history"] = {k: _sh[k] for k in _sorted_sh[:14]}

    # ── Batasi tr_records: max 200 entri ──
    _tr = st.session_state.get("tr_records", [])
    if isinstance(_tr, list) and len(_tr) > 200:
        st.session_state["tr_records"] = _tr[-200:]  # ambil 200 terbaru

    # ── FIX B7: Bersihkan insight/chart/zone cache — max 10 ticker terakhir ──
    for _prefix in ("sigma_insight_", "_alpha_chart_", "_zone_cache_", "_prefetch_done_"):
        _keys = [k for k in st.session_state if k.startswith(_prefix)]
        if len(_keys) > 10:
            for k in sorted(_keys)[:-10]:
                try:
                    del st.session_state[k]
                except Exception:
                    pass

    # ── Log ukuran session state untuk monitoring ──
    try:
        _ss_size = sys.getsizeof(str(st.session_state))
        st.session_state["_ss_size_bytes"] = _ss_size
    except Exception:
        pass


def save_user(email: str, data: dict):
    """Simpan data user dengan per-field storage untuk field kritis.
    Field kritis → row terpisah di 'user_data' (tidak bisa saling overwrite).
    Field session → satu blob di 'users' (bisa overwrite, tidak kritis)."""
    key = _ukey(email)

    # 1. Pisahkan field kritis dari data yang dikirim
    session_data = {}
    for k, v in data.items():
        if k in _PERFIELD_KEYS:
            # Hanya simpan kalau nilainya tidak kosong (tidak overwrite dengan None/{}/[])
            if v is not None and v != {} and v != []:
                _db_write("user_data", f"{key}:{k}", v)
        else:
            session_data[k] = v

    # 2. Simpan session blob (theme, sessions, dll) — overwrite OK
    if session_data:
        _db_write("users", key, session_data)
        _db_cache_ts.pop("users", None)

    # 3. Fallback lokal untuk session data
    try:
        with open(os.path.join(DATA_DIR, f"{key}.json"), "w") as f:
            json.dump(session_data, f, ensure_ascii=False)
    except Exception: pass

def save_field(email: str, field: str, value):
    """Simpan satu field kritis langsung ke Sheets tanpa menyentuh field lain.
    Gunakan ini setelah generate plan, update tr_records, dll."""
    if value is None or value == {} or value == []:
        return  # Jangan overwrite dengan kosong
    key = _ukey(email)
    if field in _PERFIELD_KEYS:
        _db_write("user_data", f"{key}:{field}", value)
    else:
        # Untuk field non-kritis, load dulu lalu merge
        existing = load_user(email) or {}
        existing[field] = value
        _db_write("users", key, existing)
        _db_cache_ts.pop("users", None)

def _async_save_field(email: str, field: str, value):
    """FIX B1: Non-blocking wrapper untuk save_field.
    Jalankan di background thread agar tidak blocking main render thread (1-3 detik).
    Gunakan ini sebagai pengganti save_field() di konteks UI (Analyze, chat save, track record update)."""
    import threading
    def _do():
        try:
            save_field(email, field, value)
        except Exception:
            pass
    threading.Thread(target=_do, daemon=True).start()

def load_user(email: str):
    """Load semua data user — merge dari 'users' (session) + 'user_data' (per-field kritis).
    Return dict lengkap semua field."""
    key = _ukey(email)
    result = {}

    # 1. Load session data dari 'users'
    try:
        all_users = _db_read_all("users")
        if key in all_users and isinstance(all_users[key], dict):
            result.update(all_users[key])
    except Exception: pass

    # 2. Load per-field kritis dari 'user_data'
    try:
        all_fields = _db_read_all("user_data")
        prefix = f"{key}:"
        for fkey, fval in all_fields.items():
            if fkey.startswith(prefix):
                field_name = fkey[len(prefix):]
                if fval is not None and fval != {} and fval != []:
                    result[field_name] = fval
    except Exception: pass

    # 3. Fallback lokal kalau Sheets gagal
    if not result:
        try:
            p = os.path.join(DATA_DIR, f"{key}.json")
            if os.path.exists(p):
                with open(p) as f:
                    result = json.load(f)
        except Exception: pass

    return result if result else None

# ── Accounts (username/password auth) ──
def get_accounts():
    """Load accounts dari SIGMA_DATABASE sheet 'accounts'. Fallback ke file lokal."""
    try:
        all_data = _db_read_all("accounts")
        if all_data:
            return all_data
    except Exception: pass
    # Fallback
    p = os.path.join(DATA_DIR, "accounts.json")
    if os.path.exists(p):
        try:
            with open(p) as f: return json.load(f)
        except Exception: pass
    return {}

def save_accounts(acc: dict):
    """Simpan setiap account sebagai row terpisah di sheet 'accounts'."""
    # Simpan setiap username sebagai key
    for username, udata in acc.items():
        _db_write("accounts", username, udata)
    # Fallback lokal
    try:
        with open(os.path.join(DATA_DIR, "accounts.json"), "w") as f:
            json.dump(acc, f)
    except Exception: pass

# ── Token auth (session token) — pakai sheet 'tokens' ──
def _save_token(token: str, info: dict):
    """Simpan session token ke Sheets + file lokal."""
    _db_write("tokens", token, info)
    try:
        with open(os.path.join(DATA_DIR, f"token_{token}.json"), "w") as f:
            json.dump(info, f)
    except Exception: pass

def _load_token(token: str):
    """Load session token dari Sheets. Fallback ke file lokal."""
    try:
        all_tokens = _db_read_all("tokens")
        if token in all_tokens:
            return all_tokens[token]
    except Exception: pass
    # Fallback
    try:
        p = os.path.join(DATA_DIR, f"token_{token}.json")
        if os.path.exists(p):
            with open(p) as f: return json.load(f)
    except Exception: pass
    return None

def _delete_token(token: str):
    """Hapus token dari cache + file lokal (tidak perlu hapus dari Sheets karena TTL natural)."""
    if "tokens" in _db_cache and token in _db_cache.get("tokens", {}):
        del _db_cache["tokens"][token]
    try:
        os.remove(os.path.join(DATA_DIR, f"token_{token}.json"))
    except Exception: pass

def register_user(username, password, display_name):
    acc = get_accounts()
    if username in acc: return False, "Username sudah dipakai"
    hashed = bcrypt.hashpw(password.encode(), bcrypt.gensalt()).decode()
    acc[username] = {"password": hashed, "display_name": display_name, "email": f"{username}@local"}
    save_accounts(acc)
    return True, "Berhasil daftar"

def login_user(username, password):
    acc = get_accounts()
    if username not in acc: return None
    if bcrypt.checkpw(password.encode(), acc[username]["password"].encode()):
        return {"email": acc[username]["email"], "name": acc[username]["display_name"], "picture": ""}
    return None


