# GROQ KEY ROTATION - AUTO SCAN KEY 1-13
# ─────────────────────────────────────────────
def _get_all_groq_keys():
    """Kumpulkan semua Groq API key yang tersedia (GROQ_API_KEY s/d GROQ_API_KEY20)."""
    key_names = ["GROQ_API_KEY"] + [f"GROQ_API_KEY{i}" for i in range(2, 21)]
    valid = []
    for key_name in key_names:
        key = st.secrets.get(key_name, "")
        if key and len(key) > 10:
            valid.append((key_name, key))
    return valid  # list of (name, key)

def _get_all_finnhub_keys():
    """Rotation FINNHUB_KEY s/d FINNHUB_KEY6."""
    names = ["FINNHUB_KEY"] + [f"FINNHUB_KEY{i}" for i in range(2, 7)]
    return [st.secrets.get(n, "") for n in names if st.secrets.get(n, "") and len(st.secrets.get(n, "")) > 10]

def _get_all_av_keys():
    """Rotation ALPHAVANTAGE_KEY s/d ALPHAVANTAGE_KEY6."""
    names = ["ALPHAVANTAGE_KEY"] + [f"ALPHAVANTAGE_KEY{i}" for i in range(2, 7)]
    return [st.secrets.get(n, "") for n in names if st.secrets.get(n, "") and len(st.secrets.get(n, "")) > 10]

def _get_all_fmp_keys():
    """Rotation FMP_KEY s/d FMP_KEY6."""
    names = ["FMP_KEY"] + [f"FMP_KEY{i}" for i in range(2, 7)]
    return [st.secrets.get(n, "") for n in names if st.secrets.get(n, "") and len(st.secrets.get(n, "")) > 10]


def _get_groq_client_and_key():
    """
    Auto-rotate melalui GROQ_API_KEY s/d GROQ_API_KEY20.
    Return (client, key_name) dari key pertama yang valid.
    """
    from groq import Groq
    valid_keys = _get_all_groq_keys()
    if not valid_keys:
        raise Exception("Semua Groq API key tidak tersedia atau tidak valid (scan KEY s/d KEY20)")
    key_name, key = valid_keys[0]
    client = Groq(api_key=key)
    return client, key_name


def _estimate_tokens(text):
    """Estimasi token count - 1 token ≈ 4 karakter (konservatif untuk Bahasa Indonesia)."""
    return max(1, len(text) // 4)

def _smart_truncate_prompt(text, max_tokens=22000):
    """
    Smart truncation: potong prompt agar tidak melebihi max_tokens.
    Prioritas: pertahankan awal (konteks/pertanyaan) & akhir (data terbaru).
    max_tokens default 22000 → sisakan ~8000 untuk system prompt + history + output.
    """
    max_chars = max_tokens * 4
    if len(text) <= max_chars:
        return text
    # Ambil 70% dari depan + 30% dari belakang - pertahankan konteks & data terbaru
    head = int(max_chars * 0.70)
    tail = max_chars-head
    # Potong di batas kalimat/newline yang bersih
    head_cut = text[:head].rfind('\n')
    if head_cut < int(head * 0.85): head_cut = text[:head].rfind('. ')
    if head_cut < 1: head_cut = head
    tail_start = len(text)-tail
    tail_cut = text.find('\n', tail_start)
    if tail_cut < 0 or tail_cut > tail_start + 200: tail_cut = tail_start
    return text[:head_cut] + "\n\n[... sebagian data tengah dipotong otomatis untuk efisiensi token ...]\n\n" + text[tail_cut:]

# ── Circuit Breaker (Bug#14 fix) ────────────────────────────────────────────
# Kalau >60% key Groq rate-limited dalam 60 detik terakhir,
# skip loop key langsung ke Gemini fallback (hemat 10-20 detik delay).
_groq_cb_window = 60   # detik window circuit breaker
_groq_cb_threshold = 0.60  # 60% key harus rate-limited baru trip

def _groq_circuit_open() -> bool:
    """Return True jika circuit breaker open (skip semua key Groq, langsung fallback)."""
    try:
        all_keys = _get_all_groq_keys()
        if not all_keys: return True
        now = time.time()
        rl_count = sum(
            1 for _, k in all_keys
            if _groq_cooldown.get(hashlib.md5(k.encode()).hexdigest()[:10], 0) > now
        )
        ratio = rl_count / len(all_keys)
        if ratio >= _groq_cb_threshold:
            # Catat circuit trip di session state untuk debug
            try: st.session_state["_groq_cb_tripped"] = True
            except Exception: pass
            return True
        try: st.session_state.pop("_groq_cb_tripped", None)
        except Exception: pass
        return False
    except Exception:
        return False
# ─────────────────────────────────────────────────────────────────────────────

def _call_groq_primary(full_prompt, history_msgs=None, max_tokens=16000, temperature=0.7):
    """
    SIGMA PRIMARY CHAIN — urutan prioritas:
      1. MiMo v2.5-Pro  (1M token context, NO truncation)
      2. Groq LLaMA 3.3 70B (key rotation, smart truncation)
      3. Gemini (fallback terakhir)
    """
    # ── LAYER 1: MiMo (coba duluan — context window terbesar, prompt masuk utuh) ──
    try:
        _mimo_resp, _mimo_mdl = _call_mimo_primary(full_prompt, history_msgs=history_msgs, max_tokens=max_tokens)
        return _mimo_resp, _mimo_mdl
    except Exception as _mimo_e:
        # MiMo gagal/rate-limit/key missing → lanjut ke Groq
        pass

    # ── LAYER 2: Groq LLaMA 3.3 70B dengan key rotation ──
    from groq import Groq

    # ── Budget token: 30.000 total context window ──
    # System prompt ~2000 token, history ~3000 token, output max_tokens → sisakan 22000 untuk prompt user
    SYSTEM_TOKEN_EST = _estimate_tokens(GROQ_SYSTEM_PROMPT)
    HISTORY_TOKEN_BUDGET = 3000   # max token untuk history
    OUTPUT_BUDGET = min(max_tokens, 16000)
    TOTAL_BUDGET = 30000
    PROMPT_BUDGET = TOTAL_BUDGET-SYSTEM_TOKEN_EST-HISTORY_TOKEN_BUDGET-OUTPUT_BUDGET
    PROMPT_BUDGET = max(PROMPT_BUDGET, 8000)  # minimal 8000 token untuk prompt

    # Truncate prompt jika melebihi budget (Groq butuh ini, MiMo tidak)
    groq_prompt = _smart_truncate_prompt(full_prompt, max_tokens=PROMPT_BUDGET)

    messages = [{"role": "system", "content": GROQ_SYSTEM_PROMPT}]

    if history_msgs:
        # Truncate setiap pesan history agar tidak membengkak
        hist_char_limit = HISTORY_TOKEN_BUDGET * 4 // 6  # bagi rata 6 pesan
        hist_clean = [
            {"role": m["role"], "content": (m.get("content") or "")[:hist_char_limit]}
            for m in history_msgs
            if m.get("role") in ("user", "assistant")
        ][-6:]
        if hist_clean and hist_clean[-1]["role"] == "user":
            hist_clean = hist_clean[:-1]
        messages.extend(hist_clean)

    messages.append({"role": "user", "content": groq_prompt})

    all_keys = _get_all_groq_keys()
    if not all_keys:
        raise Exception("Semua Groq API key tidak tersedia")

    # Bug#14: circuit breaker — skip semua key jika >60% rate-limited
    if _groq_circuit_open():
        raise Exception("Groq circuit breaker open — langsung ke Gemini fallback")

    valid_keys = _get_available_groq_keys(all_keys)

    last_err = None
    for key_name, key in valid_keys:
        if not _groq_key_available(key):
            continue
        try:
            client = Groq(api_key=key)
            response = client.chat.completions.create(
                model="llama-3.3-70b-versatile",
                messages=messages,
                temperature=temperature,
                max_tokens=OUTPUT_BUDGET
            )
            return response.choices[0].message.content, f"Groq/Llama70B({key_name})"
        except Exception as e:
            err_str = str(e).lower()
            if "429" in err_str or "rate_limit" in err_str or "rate limit" in err_str or "too large" in err_str or "token" in err_str:
                last_err = e
                _mark_groq_key_ratelimited(key)
                continue
            raise e

    # ── LAYER 3: Gemini (fallback terakhir) ──
    try:
        _gem_resp, _gem_mdl = _call_gemini_text([{"role": "user", "content": full_prompt}])
        return _gem_resp, f"Gemini(fallback-dari-Groq70B)"
    except Exception as _gem_e:
        pass  # Gemini juga gagal → lanjut ke raise

    raise Exception(f"Semua layer AI gagal (MiMo + Groq + Gemini). Groq error terakhir: {last_err}")


def _call_groq_streaming(full_prompt, max_tokens=2000, temperature=0.4):
    """
    Groq STREAMING - LLaMA 3.3 70B dengan key rotation.
    Yield chunks teks satu per satu untuk st.write_stream.
    Fallback ke Gemini jika semua key exhausted.
    """
    from groq import Groq

    full_prompt = _smart_truncate_prompt(full_prompt, max_tokens=22000)
    messages = [
        {"role": "system", "content": GROQ_SYSTEM_PROMPT},
        {"role": "user", "content": full_prompt},
    ]

    all_keys = _get_all_groq_keys()
    if not all_keys:
        raise Exception("Semua Groq API key tidak tersedia")

    valid_keys = _get_available_groq_keys(all_keys)

    last_err = None
    for key_name, key in valid_keys:
        if not _groq_key_available(key):
            continue
        try:
            client = Groq(api_key=key)
            stream = client.chat.completions.create(
                model="llama-3.3-70b-versatile",
                messages=messages,
                temperature=temperature,
                max_tokens=max_tokens,
                stream=True,
            )
            for chunk in stream:
                delta = chunk.choices[0].delta.content
                if delta:
                    yield delta
            return  # selesai normal
        except Exception as e:
            err_str = str(e).lower()
            if "429" in err_str or "rate_limit" in err_str or "rate limit" in err_str or "too large" in err_str or "token" in err_str:
                last_err = e
                _mark_groq_key_ratelimited(key)
                continue
            raise e

    # Semua Groq key exhausted → fallback Gemini (non-streaming, emit sekaligus)
    try:
        _gem_resp, _ = _call_gemini_text([{"role": "user", "content": full_prompt}])
        yield _gem_resp
        return
    except Exception:
        pass

    raise Exception(f"Semua Groq key kena rate limit & Gemini fallback gagal. Error: {last_err}")


def _call_groq_fallback(full_prompt):
    """
    Groq LAST RESORT - LLaMA 3.1 8B Instant.
    Juga rotate semua key saat 429. Smart truncation ≤ 10.000 token.
    """
    from groq import Groq

    # 8B model: context window lebih kecil → budget 10.000 token
    full_prompt = _smart_truncate_prompt(full_prompt, max_tokens=9000)

    all_keys = _get_all_groq_keys()
    if not all_keys:
        raise Exception("Semua Groq API key tidak tersedia")

    valid_keys = _get_available_groq_keys(all_keys)

    last_err = None
    for key_name, key in valid_keys:
        if not _groq_key_available(key):
            continue
        try:
            client = Groq(api_key=key)
            response = client.chat.completions.create(
                model="llama-3.1-8b-instant",
                messages=[
                    {"role": "system", "content": GROQ_SYSTEM_PROMPT},
                    {"role": "user", "content": full_prompt}
                ],
                temperature=0.7,
                max_tokens=6000
            )
            return response.choices[0].message.content, f"Groq/Llama8B({key_name})"
        except Exception as e:
            err_str = str(e).lower()
            if "429" in err_str or "rate_limit" in err_str or "rate limit" in err_str or "too large" in err_str or "token" in err_str:
                last_err = e
                _mark_groq_key_ratelimited(key)
                continue
            raise e

    raise Exception(f"Semua Groq key kena rate limit (8B). Error terakhir: {last_err}")


def _call_cerebras(full_prompt, history_msgs=None, max_tokens=8000):
    """
    Cerebras - FALLBACK KE-2 setelah Groq 70B gagal semua key.
    Model: llama-3.3-70b (throughput sangat tinggi, cocok saat Groq overload).
    """
    import urllib.request, json as _j

    MAX_CHARS = 20000
    if len(full_prompt) > MAX_CHARS:
        cutoff = full_prompt[:MAX_CHARS].rfind('\n')
        if cutoff < int(MAX_CHARS * 0.8):
            cutoff = full_prompt[:MAX_CHARS].rfind('. ')
        full_prompt = full_prompt[:cutoff if cutoff > 0 else MAX_CHARS] + "\n\n[... data dipotong]"

    cerebras_key = st.secrets.get("CEREBRAS_API_KEY", "")
    if not cerebras_key or len(cerebras_key) < 10:
        # Log ke session state agar bisa dicek di health dashboard
        if "_api_health" not in st.session_state:
            st.session_state["_api_health"] = {}
        st.session_state["_api_health"]["cerebras"] = {
            "status": "missing_key",
            "ts": _wib_now().strftime("%H:%M:%S")
        }
        raise Exception("CEREBRAS_API_KEY tidak ditemukan di Secrets — layer ini di-skip")
    else:
        if "_api_health" not in st.session_state:
            st.session_state["_api_health"] = {}
        if "cerebras" not in st.session_state["_api_health"]:
            st.session_state["_api_health"]["cerebras"] = {"status": "key_present", "ts": _wib_now().strftime("%H:%M:%S")}

    messages = [{"role": "system", "content": GROQ_SYSTEM_PROMPT}]
    if history_msgs:
        hist_clean = [
            {"role": m["role"], "content": (m.get("content") or "")[:2000]}
            for m in history_msgs
            if m.get("role") in ("user", "assistant")
        ][-6:]
        if hist_clean and hist_clean[-1]["role"] == "user":
            hist_clean = hist_clean[:-1]
        messages.extend(hist_clean)
    messages.append({"role": "user", "content": full_prompt})

    payload = {
        "model": "llama-3.3-70b",
        "messages": messages,
        "temperature": 0.7,
        "max_tokens": max_tokens
    }
    req = urllib.request.Request(
        "https://api.cerebras.ai/v1/chat/completions",
        data=_j.dumps(payload).encode(),
        headers={
            "Content-Type": "application/json",
            "Authorization": f"Bearer {cerebras_key}"
        }
    )
    with urllib.request.urlopen(req, timeout=45) as r:
        data = _j.loads(r.read())
    content_text = data["choices"][0]["message"]["content"]
    if not content_text:
        raise Exception("Cerebras mengembalikan respons kosong")
    return content_text, "Cerebras/Llama70B"


def _call_mimo_primary(full_prompt, history_msgs=None, max_tokens=16000):
    """
    MiMo PRIMARY — XiaomiMiMo v2.5-Pro via OpenAI-compatible API.
    Context window: 1.000.000 token → TIDAK ada smart_truncate, prompt masuk utuh.
    Key: st.secrets["MIMO_API_KEY"], single key (no rotation needed untuk saat ini).
    Base URL: https://api.mimoai.io/v1 (OpenAI-compatible endpoint resmi MiMo).
    """
    try:
        from openai import OpenAI as _OpenAI
    except ImportError:
        raise Exception("Library 'openai' tidak terinstall. Tambahkan ke requirements.txt: openai>=1.0.0")

    mimo_key = st.secrets.get("MIMO_API_KEY", "")
    if not mimo_key or len(mimo_key) < 10:
        if "_api_health" not in st.session_state:
            st.session_state["_api_health"] = {}
        st.session_state["_api_health"]["mimo"] = {
            "status": "missing_key",
            "ts": _wib_now().strftime("%H:%M:%S")
        }
        raise Exception("MIMO_API_KEY tidak ditemukan di Secrets — layer ini di-skip")

    if not _mimo_key_available(mimo_key):
        raise Exception("MiMo key sedang dalam cooldown rate-limit — layer ini di-skip sementara")

    # ── Update health dashboard ──
    if "_api_health" not in st.session_state:
        st.session_state["_api_health"] = {}
    if "mimo" not in st.session_state["_api_health"]:
        st.session_state["_api_health"]["mimo"] = {
            "status": "key_present",
            "ts": _wib_now().strftime("%H:%M:%S")
        }

    # ── Build messages (NO truncation — MiMo 1M token context) ──
    messages = [{"role": "system", "content": GROQ_SYSTEM_PROMPT}]

    if history_msgs:
        # History dimasukkan penuh — tidak ada char limit karena context 1M token
        hist_clean = [
            {"role": m["role"], "content": (m.get("content") or "")}
            for m in history_msgs
            if m.get("role") in ("user", "assistant")
        ][-12:]  # ambil 12 pesan terakhir (lebih banyak dari Groq karena context jauh lebih besar)
        if hist_clean and hist_clean[-1]["role"] == "user":
            hist_clean = hist_clean[:-1]
        messages.extend(hist_clean)

    messages.append({"role": "user", "content": full_prompt})

    try:
        client = _OpenAI(
            api_key=mimo_key,
            base_url="https://api.mimoai.io/v1",
        )
        response = client.chat.completions.create(
            model="mimo-v2.5-pro",
            messages=messages,
            temperature=0.7,
            max_tokens=max_tokens,
        )
        content = response.choices[0].message.content
        if not content:
            raise Exception("MiMo mengembalikan respons kosong")

        # Update health status sukses
        st.session_state["_api_health"]["mimo"] = {
            "status": "ok",
            "ts": _wib_now().strftime("%H:%M:%S")
        }
        return content, "MiMo/mimo-v2.5-pro"

    except Exception as e:
        err_str = str(e).lower()
        if "429" in err_str or "rate_limit" in err_str or "rate limit" in err_str or "quota" in err_str:
            _mark_mimo_key_ratelimited(mimo_key)
            if "_api_health" in st.session_state:
                st.session_state["_api_health"]["mimo"] = {
                    "status": "rate_limited",
                    "ts": _wib_now().strftime("%H:%M:%S")
                }
            raise Exception(f"MiMo rate-limited (429): {e}")
        # Error lain (auth, network, dll) — langsung raise agar fallback chain berjalan
        if "_api_health" in st.session_state:
            st.session_state["_api_health"]["mimo"] = {
                "status": f"error: {str(e)[:60]}",
                "ts": _wib_now().strftime("%H:%M:%S")
            }
        raise e
# ─────────────────────────────────────────────
def new_session():
    return {"id": str(uuid.uuid4())[:8], "title": "Obrolan Baru", "messages": [SYSTEM_PROMPT], "created": _wib_now().strftime("%d/%m %H:%M")}

def init_chat():
    if not st.session_state.sessions:
        s = new_session()
        st.session_state.sessions = [s]
        st.session_state.active_id = s["id"]
    else:
        for s in st.session_state.sessions:
            if not s["messages"] or s["messages"][0].get("role") != "system": s["messages"].insert(0, SYSTEM_PROMPT)
            else: s["messages"][0] = SYSTEM_PROMPT

def restore_images_from_messages():
    if not st.session_state.sessions: return
    for sesi in st.session_state.sessions:
        for i, msg in enumerate(sesi.get("messages", [])):
            if msg.get("role") == "user" and msg.get("img_b64"):
                key = f"thumb_{sesi['id']}_{i}"
                if key not in st.session_state: st.session_state[key] = (msg["img_b64"], msg.get("img_mime", "image/jpeg"))

def get_active():
    for s in st.session_state.sessions:
        if s["id"] == st.session_state.active_id: return s
    return st.session_state.sessions[0]

def google_auth_url():
    params = {"client_id": st.secrets.get("GOOGLE_CLIENT_ID", ""), "redirect_uri": st.secrets.get("GOOGLE_REDIRECT_URI", ""), "response_type": "code", "scope": "openid email profile", "access_type": "offline", "prompt": "select_account"}
    return "https://accounts.google.com/o/oauth2/v2/auth?" + urlencode(params)

def handle_oauth(code):
    r = requests.post("https://oauth2.googleapis.com/token", data={"code": code, "client_id": st.secrets.get("GOOGLE_CLIENT_ID", ""), "client_secret": st.secrets.get("GOOGLE_CLIENT_SECRET", ""), "redirect_uri": st.secrets.get("GOOGLE_REDIRECT_URI", ""), "grant_type": "authorization_code"})
    if r.status_code != 200: return None
    token = r.json().get("access_token", "")
    if not token: return None
    u = requests.get("https://www.googleapis.com/oauth2/v2/userinfo", headers={"Authorization": f"Bearer {token}"})
    return u.json() if u.status_code == 200 else None

