# SIGMA GLOBAL SCHEDULER — Dipanggil setiap page load (bukan hanya saat tab dibuka)
# Jadwal:
#   06:00 WIB  → Daily Review (Market Brief 24 jam) — auto-generate
#   15:40 WIB  → BSJP Plan — auto-generate (langsung, TANPA tunggu broker summary)
#   20:30 WIB  → Broker Summary Screening — auto-refresh (jika API tersedia)
#              → Jika broker summary gagal/limit: re-screen Daily Plan & BSJP via fallback
#   21:00 WIB  → Daily Plan — auto-generate (langsung, TANPA tunggu broker summary)
#   Sabtu 07:00 → Fundamental Screener auto-refresh
#   Sabtu 12:00 → Weekly Plan — auto-generate (langsung, TANPA tunggu broker summary)
#
# FALLBACK SCREENER: Jika sigma_bs30_screened kosong (broker summary limit/gagal),
# scheduler otomatis menjalankan Independent Watchlist Screener berbasis yfinance
# sebelum generate tiap trading plan. Tidak butuh GoAPI sama sekali.
# ═══════════════════════════════════════════════════════════════════════════════

# ── MASTER WATCHLIST untuk Independent Screener (tidak bergantung GoAPI) ──────
_SCH_WATCHLIST_CORE = [
    "BBCA","BBRI","BMRI","BBNI","BBTN","BRIS",
    "TLKM","EXCL","ISAT","TOWR","TBIG",
    "ADRO","PTBA","ITMG","HRUM","BYAN","BUMI","GEMS",
    "ANTM","MDKA","INCO","NCKL","BRMS","AMMN","MBMA",
    "ASII","UNTR","AUTO","SMSM",
    "INDF","ICBP","MYOR","UNVR","KLBF","CPIN","HMSP","GGRM",
    "SMGR","INTP","TPIA","BRPT","INKP","TKIM",
    "BSDE","CTRA","SMRA","PWON","LPKR",
    "GOTO","EMTK","MAPI","ACES","MCAS",
    "HEAL","MIKA","SILO","KAEF","TSPC",
    "PGAS","MEDC","AALI","LSIP","SIMP",
    "TBIG","LINK","RAJA","FILM","MIDI","AMRT","RALS",
    "BFIN","ADMF","PNBN","NISP","BNGA",
    "PGEO","PTRO","CUAN","VKTR","BREN",
    "SMDR","TMAS","BULL","BIRD","GIAA",
]


def _sch_independent_screener(min_spike: float = 1.5, max_tickers: int = 30) -> list:
    """
    Independent fallback screener — tidak membutuhkan GoAPI/broker summary.
    Menggunakan yfinance untuk screening volume spike dari _SCH_WATCHLIST_CORE.
    Return: list of dict (sama format dengan sigma_bs30_screened).
    """
    try:
        import yfinance as _yf_ind
        from datetime import date as _da_ind, timedelta as _tda_ind
        _end_ind   = _da_ind.today()
        _start_ind = _end_ind - _tda_ind(days=30)
        _raw_ind = _yf_ind.download(
            " ".join(f"{t}.JK" for t in _SCH_WATCHLIST_CORE),
            start=str(_start_ind), end=str(_end_ind),
            progress=False, auto_adjust=True, threads=True
        )
        _cl_ind = _raw_ind.get("Close", _raw_ind)
        _vl_ind = _raw_ind.get("Volume", None)
        _hi_ind = _raw_ind.get("High", None)
        _lo_ind = _raw_ind.get("Low", None)
        _result_ind = []
        for _tk_ind in _SCH_WATCHLIST_CORE:
            try:
                _ck = f"{_tk_ind}.JK"
                if _ck not in _cl_ind.columns: continue
                _cs = _cl_ind[_ck].dropna()
                _vs = _vl_ind[_ck].dropna() if _vl_ind is not None and _ck in _vl_ind.columns else None
                if len(_cs) < 5: continue
                _pr = float(_cs.iloc[-1])
                if _pr <= 0 or _pr > 10000: continue
                _spk = 1.0
                if _vs is not None and len(_vs) >= 20:
                    _avg20 = float(_vs.iloc[-21:-1].mean())
                    _tvol  = float(_vs.iloc[-1])
                    _spk   = round(_tvol / _avg20, 2) if _avg20 > 0 else 1.0
                if _spk < min_spike: continue
                _chg = round((_cs.iloc[-1] - _cs.iloc[-2]) / _cs.iloc[-2] * 100, 2) if len(_cs) >= 2 else 0.0
                # Ambil 5 candle terakhir untuk chart
                _n5  = min(5, len(_cs))
                _c5  = [float(_cs.iloc[-(5-i)]) for i in range(_n5)]
                _h5  = ([float(_hi_ind[_ck].dropna().iloc[-(5-i)]) for i in range(_n5)]
                        if _hi_ind is not None and _ck in _hi_ind.columns else _c5)
                _l5  = ([float(_lo_ind[_ck].dropna().iloc[-(5-i)]) for i in range(_n5)]
                        if _lo_ind is not None and _ck in _lo_ind.columns else _c5)
                _result_ind.append({
                    "ticker": _tk_ind,
                    "price":  _pr,
                    "spike":  _spk,
                    "chg1d":  _chg,
                    "high_momentum": _spk >= 2.5,
                    "momentum_days": 0,
                    "verdict": "VOL_SPIKE" if _spk >= 2.0 else "WATCH",
                    "pre_accum": _spk >= 1.5,
                    "top_accum": [], "top_dist": [],
                    "accum_days": 0,
                    "goapi_confirmed": False,
                    "closes5": _c5, "highs5": _h5, "lows5": _l5,
                    "_source": "fallback_yfinance",
                })
            except Exception:
                continue
        _result_ind.sort(key=lambda x: x["spike"], reverse=True)
        return _result_ind[:max_tickers]
    except Exception:
        return []


def _sch_ensure_bs30(now_sch, today_s: str) -> list:
    """
    Pastikan sigma_bs30_screened tersedia.
    Prioritas: (1) cache session, (2) brosum_history, (3) independent screener.
    Return list yang siap dipakai — tidak pernah raise.
    """
    # Prioritas 1: sudah ada di session
    _bs30 = st.session_state.get("sigma_bs30_screened") or []
    if _bs30:
        return _bs30

    # Prioritas 2: dari brosum_history (hari lain)
    _bsh = st.session_state.get("brosum_history", {})
    if _bsh:
        _last_key = sorted(_bsh.keys())[-1]
        _bs30 = _bsh[_last_key].get("screened", [])
        if _bs30:
            return _bs30

    # Prioritas 3: independent screener (fallback tanpa GoAPI)
    try:
        _fallback = _sch_independent_screener(min_spike=1.5, max_tickers=30)
        if _fallback:
            _ts_fb = now_sch.strftime("%d %b %Y, %H:%M WIB (Fallback Screener)")
            st.session_state["sigma_bs30_screened"] = _fallback
            st.session_state["sigma_bs30_ts"]       = _ts_fb
            # Simpan ke brosum_history agar dipakai plan berikutnya
            _bsh2 = st.session_state.get("brosum_history", {})
            _bsh2[today_s] = {
                "date": now_sch.strftime("%d %b %Y"),
                "generated_at": _ts_fb,
                "screened": _fallback,
                "source": "fallback_yfinance",
            }
            st.session_state["brosum_history"] = _bsh2
            try:
                _ue_fb = st.session_state.get("user", {}).get("email", "")
                if _ue_fb:
                    save_field(_ue_fb, "sigma_bs30_screened", _fallback)
                    save_field(_ue_fb, "sigma_bs30_ts",       _ts_fb)
                    save_field(_ue_fb, "brosum_history",      _bsh2)
            except Exception:
                pass
            return _fallback
    except Exception:
        pass
    return []


def _sigma_run_global_scheduler():
    """Master scheduler — dipanggil di setiap page rerun."""
    if not st.session_state.get("user"):
        return  # hanya untuk user yang sudah login

    # ── Fast-path: jalankan max 1x per 60 detik ──────────────────
    import time as _t_sch_guard
    _sch_last = st.session_state.get("_sch_last_run_ts", 0)
    if _t_sch_guard.time() - _sch_last < 60:
        return  # belum waktunya, skip seluruh scheduler
    st.session_state["_sch_last_run_ts"] = _t_sch_guard.time()
    # ─────────────────────────────────────────────────────────────

    from datetime import timezone, timedelta as _td_sch
    _wib_sch  = timezone(_td_sch(hours=7))
    _now_sch  = datetime.now(_wib_sch)
    _wd_sch   = _now_sch.weekday()        # 0=Senin … 6=Minggu
    _today_s  = _now_sch.strftime("%Y-%m-%d")
    _hour_s   = _now_sch.hour
    _min_s    = _now_sch.minute

    def _is_weekday(): return _wd_sch < 5
    def _past(h, m=0): return _hour_s > h or (_hour_s == h and _min_s >= m)

    # ── Bersihkan guard key dari hari-hari lalu agar tidak menghambat generate hari baru ──
    _guard_prefixes = ["daily_plan_global_", "bsjp_plan_global_", "brosum_global_auto_",
                       "daily_review_auto_", "weekly_plan_global_", "tr_post_key_",
                       "tr_post_bsjp_", "tr_update_open_", "_bsjp_bs_upgraded_", "_wp_bs_upgraded_",
                       "tr_intra_", "tr_final_"]
    _keys_to_del = [
        k for k in list(st.session_state.keys())
        if any(k.startswith(p) for p in _guard_prefixes)
        and not k.endswith(_today_s)
        and not k.endswith(_now_sch.strftime("%G-W%V"))
    ]
    for _gk in _keys_to_del:
        try: del st.session_state[_gk]
        except: pass

    # ── Restore data dari DB jika session baru ──────────────────────────────
    # Skip jika data_loaded=True — semua key sudah di-restore oleh blok utama
    if not st.session_state.get("data_loaded"):
        _restore_keys_sch = [
            "auto_plan_history_daily", "auto_plan_history_weekly",
            "auto_plan_history_bsjp", "tr_records", "brosum_history",
            "sigma_bs30_screened", "sigma_bs30_ts",
            "mb_daily_content", "mb_daily_timestamp",
        ]
        _need_restore = any(k not in st.session_state for k in _restore_keys_sch)
        if _need_restore:
            try:
                _sv_sch = load_user(st.session_state.user["email"]) or {}
                for _rk in _restore_keys_sch:
                    if _rk not in st.session_state and _sv_sch.get(_rk) is not None:
                        st.session_state[_rk] = _sv_sch[_rk]
            except Exception: pass

    # ══════════════════════════════════════════════════════════════
    # [1] JAM 06:00 — DAILY REVIEW (Market Brief 24 Jam) AUTO-GENERATE
    # ══════════════════════════════════════════════════════════════
    if _is_weekday() and _past(6):
        _dr_auto_key = f"daily_review_auto_{_today_s}"
        if not st.session_state.get(_dr_auto_key):
            # Cek apakah sudah ada review hari ini
            _mb_ts = st.session_state.get("mb_daily_timestamp", "")
            _mb_content = st.session_state.get("mb_daily_content", "")
            _already_today_dr = _today_s in _mb_ts if _mb_ts else False

            if not _already_today_dr or not _mb_content:
                st.session_state[_dr_auto_key] = True  # lock dulu
                try:
                    import feedparser as _fp_sch
                    _wib_tz2 = timezone(_td_sch(hours=7))
                    _now_dr  = datetime.now(_wib_tz2)
                    _cutoff_dr = _now_dr - _td_sch(hours=24)

                    dom_news_sch, glob_news_sch = [], []
                    _rss_sch = [
                        ("https://www.cnbcindonesia.com/market/rss",          dom_news_sch),
                        ("https://www.cnbcindonesia.com/economy/rss",         dom_news_sch),
                        ("https://www.cnbc.com/id/15839069/device/rss/rss.html", glob_news_sch),
                        ("https://feeds.a.dj.com/rss/RSSMarketsMain.xml",     glob_news_sch),
                        ("https://feeds.bbci.co.uk/news/world/rss.xml",       glob_news_sch),
                    ]
                    for _url_sch, _target_sch in _rss_sch:
                        try:
                            _feed_sch = _fp_sch.parse(_url_sch)
                            for _e_sch in _feed_sch.entries[:12]:
                                _t_sch = _e_sch.get("title","").strip()
                                if _t_sch and _t_sch not in _target_sch:
                                    _target_sch.append(_t_sch)
                                    if len(_target_sch) >= 12: break
                        except Exception: pass

                    import yfinance as _yf_dr
                    _rt_sch = {}
                    for _sym_dr, _key_dr in [("^JKSE","ihsg"),("USDIDR=X","usdidr"),("GC=F","gold"),
                                              ("CL=F","wti"),("^GSPC","spx"),("^DJI","dji")]:
                        try:
                            _hw_dr = _yf_dr.Ticker(_sym_dr).history(period="5d")
                            if not _hw_dr.empty:
                                _lv = float(_hw_dr["Close"].iloc[-1])
                                _pv = float(_hw_dr["Close"].iloc[-2]) if len(_hw_dr)>1 else _lv
                                _cv = round((_lv-_pv)/_pv*100, 2) if _pv else 0
                                _rt_sch[f"{_key_dr}_price"] = round(_lv,2)
                                _rt_sch[f"{_key_dr}_chg"]   = _cv
                        except Exception: pass

                    _today_str_dr = _now_dr.strftime("%d %B %Y, %H:%M WIB")
                    _dom_str_dr   = "\n".join(f"• {h}" for h in dom_news_sch[:10]) or "⚠ Tidak tersedia"
                    _glob_str_dr  = "\n".join(f"• {h}" for h in glob_news_sch[:10]) or "⚠ Tidak tersedia"

                    def _fmt_rt(d):
                        out = []
                        for pk,ck,nm,pre,suf in [
                            ("ihsg_price","ihsg_chg","IHSG","",""),
                            ("usdidr_price","usdidr_chg","USD/IDR","Rp ",""),
                            ("gold_price","gold_chg","Gold XAU","$",""),
                            ("wti_price","wti_chg","WTI Oil","$","/bbl"),
                            ("spx_price","spx_chg","S&P 500","",""),
                        ]:
                            if d.get(pk):
                                _c = d.get(ck,0)
                                _a = "▲" if _c>=0 else "▼"
                                if pk=="usdidr_price":
                                    out.append(f"• {nm}: {pre}{d[pk]:,.0f}{suf} ({_a}{abs(_c):.2f}%)")
                                else:
                                    out.append(f"• {nm}: {pre}{d[pk]:,.2f}{suf} ({_a}{abs(_c):.2f}%)")
                        return "\n".join(out) if out else "Data tidak tersedia"

                    _rt_block_dr = _fmt_rt(_rt_sch)

                    _dr_prompt = f"""Kamu adalah Chief Market Analyst SIGMA.
Tanggal & waktu sekarang: **{_today_str_dr}** | Mode: **DAILY REVIEW - 24 JAM TERAKHIR**

(!) Bahas HANYA berita dan data dalam 24 JAM TERAKHIR.

=== DATA HARGA REAL-TIME ===
{_rt_block_dr}
(!) GUNAKAN ANGKA INI PERSIS. JANGAN UBAH.
===========================

BERITA DOMESTIK:
{_dom_str_dr}

BERITA GLOBAL:
{_glob_str_dr}

FORMAT - Bahasa Indonesia, max 600 kata, Markdown:
##  IHSG & PASAR DOMESTIK HARI INI
##  KATALIS GLOBAL 24 JAM TERAKHIR
##  GEOPOLITIK & RISIKO GLOBAL
##  FOREX & KOMODITAS
##  SENTIMENT METER
##  TACTICAL VIEW
##  WATCHLIST SEKTORAL (3 sektor)

Padat & actionable. JANGAN UBAH ANGKA REAL-TIME. Waktu dalam WIB."""

                    _dr_result = None
                    # ── [FIXED] Ganti Anthropic → Gemini (lebih cepat, tidak butuh ANTHROPIC_API_KEY) ──
                    try:
                        _dr_result, _ = _call_gemini_text([{"role": "user", "content": _dr_prompt}])
                        if not _dr_result: _dr_result = None
                    except Exception: _dr_result = None

                    if not _dr_result:
                        try:
                            _groq_sch = Groq(api_key=st.secrets.get("GROQ_API_KEY",""))
                            _resp_sch  = _groq_sch.chat.completions.create(
                                model="llama-3.3-70b-versatile",
                                messages=[{"role":"user","content":_dr_prompt}],
                                max_tokens=3000,
                            )
                            _dr_result = _resp_sch.choices[0].message.content
                        except Exception: pass

                    if _dr_result:
                        _dr_result += f"\n\n---\n*Auto-generated jam 06:00 WIB · {_today_str_dr}*"
                        st.session_state["mb_daily_content"]   = _dr_result
                        st.session_state["mb_daily_timestamp"] = _today_str_dr
                        try:
                            _sv_dr = load_user(st.session_state.user["email"]) or {}
                            _sv_dr["mb_daily_content"]   = _dr_result
                            _sv_dr["mb_daily_timestamp"] = _today_str_dr
                            save_user(st.session_state.user["email"], _sv_dr)
                        except Exception: pass
                    else:
                        # Gagal generate — unlock agar bisa retry
                        del st.session_state[_dr_auto_key]
                except:
                    if _dr_auto_key in st.session_state:
                        del st.session_state[_dr_auto_key]

    # ══════════════════════════════════════════════════════════════
    # [2] JAM 20:30 — BROKER SUMMARY SCREENING AUTO-REFRESH
    # ══════════════════════════════════════════════════════════════
    if _is_weekday() and _past(20, 30):
        _bs_auto_key = f"brosum_global_auto_{_today_s}"
        if not st.session_state.get(_bs_auto_key):
            # Cek apakah sudah ada di history hari ini (key = YYYY-MM-DD)
            _bsh_chk = st.session_state.get("brosum_history", {})
            _already_bs = _today_s in _bsh_chk
            if not _already_bs:
                st.session_state[_bs_auto_key] = True
                try:
                    import yfinance as _yf_bs
                    from datetime import date as _da_bs, timedelta as _tda_bs
                    _BS30 = [
                        "TLKM","ASII","UNVR","ICBP","INDF","KLBF","GGRM","HMSP","MYOR","CPIN",
                        "ADRO","ITMG","PTBA","ANTM","INCO","MDKA","NCKL","MBMA","BRMS","AMMN",
                        "SMGR","INTP","BSDE","CTRA","SMRA","PWON","GOTO","EMTK","MAPI","ACES",
                        "HEAL","MIKA","SILO","KAEF","TSPC","PGAS","MEDC","AALI","LSIP","SIMP",
                        "TBIG","TOWR","LINK","TPIA","BRPT","UNTR","BFIN","ADMF","TMAS","SMDR",
                        "PGEO","PTRO","CUAN","VKTR","RAJA","FILM","MIDI","RALS","AMRT","MCAS",
                    ]
                    _end_bs   = _da_bs.today()
                    _start_bs = _end_bs - _tda_bs(days=30)
                    _raw_bs   = _yf_bs.download(
                        " ".join(f"{t}.JK" for t in _BS30),
                        start=str(_start_bs), end=str(_end_bs),
                        progress=False, auto_adjust=True, threads=True
                    )
                    _cl_bs = _raw_bs.get("Close", _raw_bs)
                    _vl_bs = _raw_bs.get("Volume", None)
                    _result_bs = []
                    for _tk_bs in _BS30:
                        try:
                            _ck_bs = f"{_tk_bs}.JK"
                            if _ck_bs not in _cl_bs.columns: continue
                            _cs_bs = _cl_bs[_ck_bs].dropna()
                            _vs_bs = _vl_bs[_ck_bs].dropna() if _vl_bs is not None and _ck_bs in _vl_bs.columns else None
                            if len(_cs_bs) < 5: continue
                            _pr_bs = float(_cs_bs.iloc[-1])
                            if _pr_bs > 8000: continue
                            _spk_bs = 1.0
                            if _vs_bs is not None and len(_vs_bs) >= 20:
                                _avg20_bs = float(_vs_bs.iloc[-21:-1].mean())
                                _tvol_bs  = float(_vs_bs.iloc[-1])
                                _spk_bs   = round(_tvol_bs / _avg20_bs, 2) if _avg20_bs > 0 else 1.0
                            if _spk_bs < 1.5: continue
                            _chg_bs = round((_cs_bs.iloc[-1]-_cs_bs.iloc[-2])/_cs_bs.iloc[-2]*100, 2) if len(_cs_bs)>=2 else 0
                            _result_bs.append({
                                "ticker": _tk_bs, "price": _pr_bs, "spike": _spk_bs, "chg1d": _chg_bs,
                                "high_momentum": False, "momentum_days": 0, "verdict": "",
                                "pre_accum": _spk_bs >= 1.5, "top_accum": [], "top_dist": [],
                                "accum_days": 0, "goapi_confirmed": False
                            })
                        except: continue

                    if _result_bs:
                        _result_bs.sort(key=lambda x: x["spike"], reverse=True)
                        _ts_new = _now_sch.strftime("%d %b %Y, %H:%M WIB (Auto 20:30)")
                        st.session_state["sigma_bs30_screened"] = _result_bs[:30]
                        st.session_state["sigma_bs30_ts"]       = _ts_new
                        # Simpan ke history
                        _bsh_sch = st.session_state.get("brosum_history", {})
                        _bsh_sch[_today_s] = {
                            "date": _now_sch.strftime("%d %b %Y"),
                            "generated_at": _ts_new,
                            "screened": _result_bs[:30],
                            "source": "broker",
                        }
                        if len(_bsh_sch) > 30:
                            for _dk_sch in sorted(_bsh_sch.keys())[:-30]:
                                del _bsh_sch[_dk_sch]
                        st.session_state["brosum_history"] = _bsh_sch
                        # Simpan ke Sheets — per-field, tidak bisa overwrite field lain
                        try:
                            _ue = st.session_state.user["email"]
                            save_field(_ue, "sigma_bs30_screened", _result_bs[:30])
                            save_field(_ue, "sigma_bs30_ts",       _ts_new)
                            save_field(_ue, "brosum_history",      _bsh_sch)
                        except Exception: pass
                    else:
                        del st.session_state[_bs_auto_key]
                except:
                    if _bs_auto_key in st.session_state:
                        del st.session_state[_bs_auto_key]

    # ══════════════════════════════════════════════════════════════
    # [3] JAM 21:00 — DAILY PLAN AUTO-GENERATE
    # Berjalan TANPA menunggu broker summary.
    # Fallback otomatis ke independent screener jika bs30 kosong.
    # Re-generate jika broker summary baru tersedia (upgrade plan).
    # ══════════════════════════════════════════════════════════════
    if _is_weekday() and _past(21):
        _dp_auto_key = f"daily_plan_global_{_today_s}"
        if not st.session_state.get(_dp_auto_key):
            _dph = st.session_state.get("auto_plan_history_daily", {})
            _slot_dp = f"{_today_s}_2100"
            # Cek apakah broker summary real (bukan fallback) tersedia hari ini
            _bsh_dp_chk   = st.session_state.get("brosum_history", {})
            _bs_real_today = (_today_s in _bsh_dp_chk and
                              _bsh_dp_chk[_today_s].get("source") != "fallback_yfinance")
            _dp_upg_key   = f"_dp_bs_upgraded_{_today_s}"
            _slot_dp_src  = _dph.get(_slot_dp, {}).get("source", "")
            _slot_dp_exists = (_slot_dp in _dph and
                               bool(_dph[_slot_dp].get("plan",{}).get("daily",[])))
            # Paksa regenerate jika sebelumnya dari fallback tapi sekarang broker summary real tersedia
            if _slot_dp_exists and _slot_dp_src == "fallback_yfinance" and _bs_real_today and not st.session_state.get(_dp_upg_key):
                _slot_dp_exists = False
                st.session_state[_dp_upg_key] = True
            if not _slot_dp_exists:
                st.session_state[_dp_auto_key] = True
                try:
                    # _sch_ensure_bs30: session → history → independent screener (fallback)
                    _bs30_dp = _sch_ensure_bs30(_now_sch, _today_s)
                    if _bs30_dp:
                        _bs30_dp_src = (st.session_state.get("brosum_history", {})
                                        .get(_today_s, {}).get("source", "broker"))
                        _tickers_dp = tuple(s["ticker"] for s in _bs30_dp if s.get("ticker"))
                        # Bug #4 fix: gunakan _reco_fetch_prices + _rule_based_plan_v2
                        # (bukan hardcoded entry/tp/sl persentase kasar)
                        try:
                            _pm_dp = _reco_fetch_prices(_tickers_dp)
                        except Exception:
                            _pm_dp = {}
                        if _pm_dp:
                            _src_note = "" if _bs30_dp_src != "fallback_yfinance" else " · Screened via fallback (broker API limit)"
                            try:
                                _plan_dp = _rule_based_plan_v2(_pm_dp, _bs30_dp, "daily")
                                if _plan_dp:
                                    _plan_dp["outlook"] = (_plan_dp.get("outlook") or "") + f" · Auto-generated jam 21:00 WIB{_src_note}"
                            except Exception:
                                _plan_dp = None
                            if _plan_dp and _plan_dp.get("daily"):
                                _dph_cur = st.session_state.get("auto_plan_history_daily", {})
                                _gen_at  = _now_sch.strftime("%d %b %Y, %H:%M WIB")
                                _dph_cur[_slot_dp] = {
                                    "date": _now_sch.strftime("%d %b %Y"),
                                    "slot": "Sesi Malam (21:00)",
                                    "plan": _plan_dp,
                                    "generated_at": _gen_at,
                                    "source": _bs30_dp_src,
                                }
                                st.session_state["auto_plan_history_daily"] = _dph_cur
                                try:
                                    save_field(st.session_state.user["email"], "auto_plan_history_daily", _dph_cur)
                                except Exception: pass
                except:
                    if _dp_auto_key in st.session_state:
                        del st.session_state[_dp_auto_key]

    # ══════════════════════════════════════════════════════════════
    # [4] JAM 15:40 — BSJP PLAN AUTO-GENERATE
    # Berjalan TANPA menunggu broker summary.
    # Fallback otomatis ke independent screener jika bs30 kosong.
    # Re-generate jika broker summary baru tersedia (upgrade plan).
    # ══════════════════════════════════════════════════════════════
    if _is_weekday() and _past(15, 40):
        _bsjp_auto_key = f"bsjp_plan_global_{_today_s}"
        if not st.session_state.get(_bsjp_auto_key):
            _bsjp_h = st.session_state.get("auto_plan_history_bsjp", {})
            _slot_bsjp = f"{_today_s}_1540"
            _bsh_bsjp_chk = st.session_state.get("brosum_history", {})
            _bs_real_bsjp = (_today_s in _bsh_bsjp_chk and
                             _bsh_bsjp_chk[_today_s].get("source") != "fallback_yfinance")
            _bsjp_upg_key = f"_bsjp_bs_upgraded_{_today_s}"
            _slot_bsjp_src = _bsjp_h.get(_slot_bsjp, {}).get("source", "")
            _slot_bsjp_exists = (_slot_bsjp in _bsjp_h and
                                 bool(_bsjp_h[_slot_bsjp].get("plan",{}).get("bsjp",[])))
            if _slot_bsjp_exists and _slot_bsjp_src == "fallback_yfinance" and _bs_real_bsjp and not st.session_state.get(_bsjp_upg_key):
                _slot_bsjp_exists = False
                st.session_state[_bsjp_upg_key] = True
            if not _slot_bsjp_exists:
                st.session_state[_bsjp_auto_key] = True
                try:
                    # _sch_ensure_bs30: session → history → independent screener (fallback)
                    _bs30_bsjp = _sch_ensure_bs30(_now_sch, _today_s)
                    _bs30_bsjp_src = (st.session_state.get("brosum_history", {})
                                      .get(_today_s, {}).get("source", "broker"))
                    if _bs30_bsjp:
                        import yfinance as _yf_bsjp
                        _pm_bsjp = {}
                        _tickers_bsjp = [s["ticker"] for s in _bs30_bsjp if s.get("ticker")][:30]
                        for _tk_bsjp in _tickers_bsjp:
                            try:
                                _h_bsjp = _yf_bsjp.Ticker(f"{_tk_bsjp}.JK").history(period="5d")
                                if not _h_bsjp.empty:
                                    _pm_bsjp[_tk_bsjp] = {
                                        "close": float(_h_bsjp["Close"].iloc[-1]),
                                        "high":  float(_h_bsjp["High"].iloc[-1]),
                                        "low":   float(_h_bsjp["Low"].iloc[-1]),
                                        "volume":float(_h_bsjp["Volume"].iloc[-1]) if "Volume" in _h_bsjp else 0,
                                        "prev_close": float(_h_bsjp["Close"].iloc[-2]) if len(_h_bsjp)>1 else float(_h_bsjp["Close"].iloc[-1]),
                                    }
                            except Exception: pass
                        if _pm_bsjp:
                            _src_note_b = "" if _bs30_bsjp_src != "fallback_yfinance" else " · Screened via fallback (broker API limit)"
                            _plan_bsjp = {"bsjp": [], "avoid": [], "outlook": f"Auto-generated jam 15:40 WIB (Sesi Closing BEI){_src_note_b}"}
                            for _s_bsjp in _bs30_bsjp[:20]:
                                _tk_b2 = _s_bsjp.get("ticker","")
                                if _tk_b2 not in _pm_bsjp: continue
                                _pd_b2 = _pm_bsjp[_tk_b2]
                                _cl_b2 = _pd_b2["close"]
                                _spk_b = _s_bsjp.get("spike",1.0)
                                # BSJP: beli closing hari ini, jual besok pagi
                                if _spk_b >= 1.8 and _pd_b2.get("close",0) > 0:
                                    _tp_b = round(_cl_b2 * 1.03)
                                    _sl_b = round(_cl_b2 * 0.98)
                                    _plan_bsjp["bsjp"].append({
                                        "ticker": _tk_b2, "price": int(_cl_b2),
                                        "entry_low": int(_cl_b2*0.998), "entry_high": int(_cl_b2*1.002),
                                        "tp1": _tp_b, "tp2": round(_cl_b2*1.05),
                                        "sl": _sl_b, "rr": "1:1.5",
                                        "horizon": "H+1 pagi",
                                        "rating": "BSJP",
                                        "vol_spike": f"{_spk_b:.1f}x",
                                        "why_buy": f"Spike {_spk_b:.1f}x closing · Target gap-up H+1",
                                    })
                            if _plan_bsjp["bsjp"]:
                                _bsjp_h_cur = st.session_state.get("auto_plan_history_bsjp", {})
                                _gen_bsjp   = _now_sch.strftime("%d %b %Y, %H:%M WIB")
                                _bsjp_h_cur[_slot_bsjp] = {
                                    "date": _now_sch.strftime("%d %b %Y"),
                                    "slot": "Sesi Closing (15:40)",
                                    "plan": _plan_bsjp,
                                    "generated_at": _gen_bsjp,
                                    "source": _bs30_bsjp_src,
                                }
                                st.session_state["auto_plan_history_bsjp"] = _bsjp_h_cur
                                try:
                                    save_field(st.session_state.user["email"], "auto_plan_history_bsjp", _bsjp_h_cur)
                                except Exception: pass
                except:
                    if _bsjp_auto_key in st.session_state:
                        del st.session_state[_bsjp_auto_key]

    # ══════════════════════════════════════════════════════════════
    # [4b] JAM 16:00 — AUTO-UPDATE TRACK RECORD POST-BSJP
    # Cek TP/SL 20 menit setelah market close untuk posisi BSJP hari ini
    # ══════════════════════════════════════════════════════════════
    if _wd_sch < 5 and _past(15, 45):  # Senin-Jumat jam 15:45+ (setelah BSJP generate)
        _tr_post_key = f"tr_post_bsjp_{_today_s}"
        if not st.session_state.get(_tr_post_key):
            try:
                _records_post = st.session_state.get("tr_records", [])
                _open_post = [r for r in _records_post
                              if r.get("status") == "OPEN"
                              and (r.get("type","").upper() in ("BSJP","DAILY")
                                   or r.get("plan_type","").upper() in ("BSJP","DAILY"))]
                if _open_post:
                    import yfinance as _yf_post
                    import threading as _thr_post
                    _prices_post = {}
                    _lock_post = _thr_post.Lock()
                    def _fetch_post(tk):
                        try:
                            # Pakai interval 1m period 1d untuk high/low intraday paling akurat
                            h1m = _yf_post.Ticker(f"{tk}.JK").history(period="1d", interval="1m")
                            if not h1m.empty:
                                with _lock_post:
                                    _prices_post[tk] = {
                                        "high":  float(h1m["High"].max()),
                                        "low":   float(h1m["Low"].min()),
                                        "close": float(h1m["Close"].iloc[-1]),
                                    }
                                return
                            # Fallback: daily
                            h = _yf_post.Ticker(f"{tk}.JK").history(period="2d")
                            if not h.empty:
                                with _lock_post:
                                    _prices_post[tk] = {
                                        "high":  float(h["High"].iloc[-1]),
                                        "low":   float(h["Low"].iloc[-1]),
                                        "close": float(h["Close"].iloc[-1]),
                                    }
                        except Exception: pass
                    _tks_post = list(set(r["ticker"] for r in _open_post))
                    _ts_post = [_thr_post.Thread(target=_fetch_post, args=(t,)) for t in _tks_post]
                    for t in _ts_post: t.start()
                    for t in _ts_post: t.join(timeout=10)
                    _changed_post = False
                    for r in _records_post:
                        if r.get("status") != "OPEN": continue
                        tk = r["ticker"]
                        if tk not in _prices_post: continue
                        hi = _prices_post[tk]["high"]
                        lo = _prices_post[tk]["low"]
                        _e_lo = r.get("entry_low", r.get("entry", 0)) or 0
                        _e_hi = r.get("entry_high", _e_lo) or _e_lo
                        entry = (_e_lo + _e_hi) // 2 if _e_lo and _e_hi else r.get("entry", 0)
                        tp1 = r.get("tp1", 0) or 0
                        tp2 = r.get("tp2", 0) or 0
                        sl  = r.get("sl",  0) or 0
                        if entry <= 0: continue
                        _now_s = _now_sch.strftime("%d %b %Y, %H:%M WIB")
                        # ── VALIDASI: harga hari ini harus menyentuh area entry dulu ──
                        # LOW harus ≤ entry_high agar bisa dianggap terbeli di zona
                        _entry_touched = lo <= (_e_hi if _e_hi else entry)
                        if not _entry_touched:
                            # Harga tidak pernah masuk zona buy — skip, tandai sebagai NOT_TRIGGERED
                            r["auto_note"] = f"⏭️ Entry tidak tersentuh (Low={int(lo):,} > EntryHi={int(_e_hi if _e_hi else entry):,}) — tidak terbeli ({_now_s})"
                            r["not_triggered"] = True
                            _changed_post = True
                            continue
                        r.pop("not_triggered", None)
                        if tp2 > 0 and hi >= tp2:
                            r.update({"status": "TP2", "exit_price": tp2, "result": "WIN",
                                      "pnl_pct": round((tp2-entry)/entry*100, 2),
                                      "exit_date": _today_s, "auto_note": f"🎯 TP2 Rp{tp2:,} tersentuh post-market ({_now_s})"})
                            _changed_post = True
                        elif tp1 > 0 and hi >= tp1:
                            r.update({"status": "TP1", "exit_price": tp1, "result": "WIN",
                                      "pnl_pct": round((tp1-entry)/entry*100, 2),
                                      "exit_date": _today_s, "auto_note": f"✅ TP1 Rp{tp1:,} tersentuh post-market ({_now_s})"})
                            _changed_post = True
                        elif sl > 0 and lo <= sl:
                            r.update({"status": "SL", "exit_price": sl, "result": "LOSS",
                                      "pnl_pct": round((sl-entry)/entry*100, 2),
                                      "exit_date": _today_s, "auto_note": f"🛑 SL Rp{sl:,} tersentuh post-market ({_now_s})"})
                            _changed_post = True
                    if _changed_post:
                        st.session_state["tr_records"] = _records_post
                        if st.session_state.get("user"):
                            try: save_field(st.session_state.user["email"], "tr_records", _records_post)
                            except Exception: pass
                st.session_state[_tr_post_key] = True
            except Exception: pass

    # ══════════════════════════════════════════════════════════════
    # [5a] SABTU JAM 07:00 — FUNDAMENTAL SCREENER AUTO-REFRESH
    # Cache 7 hari — refresh setiap Sabtu pagi sebelum Weekly Plan
    # ══════════════════════════════════════════════════════════════
    if _wd_sch == 5 and _past(7) and not _past(8):  # Sabtu jam 07:00-08:00
        _fs_auto_key = f"fs_auto_{_now_sch.strftime('%G-W%V')}"
        if not st.session_state.get(_fs_auto_key) and st.session_state.get("user"):
            try:
                # Cek apakah sudah pernah refresh minggu ini
                _fs_ts_stored = st.session_state.get("fs_ts", "")
                _fs_week_done = False
                if _fs_ts_stored:
                    try:
                        _fs_dt2 = datetime.strptime(_fs_ts_stored[:11].strip(), "%d %b %Y")
                        _fs_week_done = (datetime.now() - _fs_dt2).days < 7
                    except Exception: pass
                if not _fs_week_done:
                    import yfinance as _yf_fs, threading as _thr_fs
                    _fs_auto_tickers = tuple(_WATCHLIST_RECO[:80])  # top 80 watchlist
                    _fs_auto_results = {}
                    _fs_lock = _thr_fs.Lock()
                    def _fs_auto_one(tk):
                        try:
                            inf = _yf_fs.Ticker(f"{tk}.JK").info
                            roe = (inf.get("returnOnEquity") or 0)*100
                            npm = (inf.get("profitMargins") or 0)*100
                            der = inf.get("debtToEquity") or 0
                            cr  = inf.get("currentRatio") or 0
                            pbv = inf.get("priceToBook") or 0
                            eps = inf.get("trailingEps") or 0
                            score = sum([roe>=15, der<=1.0 and der>0, npm>=10, cr>=1.5, 0.5<=pbv<=3.0 and pbv>0, eps>0])
                            with _fs_lock:
                                _fs_auto_results[tk] = {
                                    "name": (inf.get("shortName") or tk)[:22],
                                    "price": inf.get("currentPrice") or inf.get("regularMarketPrice") or 0,
                                    "roe":roe,"npm":npm,"der":der,"cr":cr,"pbv":pbv,"eps":eps,"score":score,
                                    "roa": (inf.get("returnOnAssets") or 0)*100,
                                    "pe": inf.get("trailingPE") or 0,
                                    "div": (inf.get("dividendYield") or 0)*100,
                                    "mkcap": inf.get("marketCap") or 0,
                                    "eps_g": 0,
                                }
                        except Exception: pass
                    _fs_ths = [_thr_fs.Thread(target=_fs_auto_one, args=(t,)) for t in _fs_auto_tickers]
                    for t in _fs_ths: t.start()
                    for t in _fs_ths: t.join(timeout=25)
                    if _fs_auto_results:
                        _fs_auto_ts = _wib_now().strftime("%d %b %Y, %H:%M WIB")
                        st.session_state["fs_results"] = _fs_auto_results
                        st.session_state["fs_ts"]      = _fs_auto_ts
                        st.session_state["fs_sektor"]  = "Semua Sektor"
                        _ue_fsa = st.session_state.user["email"]
                        save_field(_ue_fsa, "fs_results", _fs_auto_results)
                        save_field(_ue_fsa, "fs_ts",      _fs_auto_ts)
                        save_field(_ue_fsa, "fs_sektor",  "Semua Sektor")
                st.session_state[_fs_auto_key] = True
            except:
                if _fs_auto_key in st.session_state:
                    del st.session_state[_fs_auto_key]

    # ══════════════════════════════════════════════════════════════
    # [5] SABTU JAM 12:00 — WEEKLY PLAN AUTO-GENERATE
    # ══════════════════════════════════════════════════════════════
    if _wd_sch == 5 and _past(12):  # Sabtu
        _week_iso = _now_sch.strftime("%G-W%V")
        _wp_auto_key = f"weekly_plan_global_{_week_iso}"
        if not st.session_state.get(_wp_auto_key):
            _wph = st.session_state.get("auto_plan_history_weekly", {})
            _slot_wp = f"{_week_iso}_1200"
            # Cek upgrade: jika sebelumnya dari fallback tapi broker summary real sudah ada
            _bsh_wp_chk   = st.session_state.get("brosum_history", {})
            _bs_real_wp   = any(
                v.get("source") != "fallback_yfinance"
                for v in _bsh_wp_chk.values()
            ) if _bsh_wp_chk else False
            _wp_upg_key   = f"_wp_bs_upgraded_{_week_iso}"
            _slot_wp_src  = _wph.get(_slot_wp, {}).get("source", "")
            _slot_wp_exists = _slot_wp in _wph and bool(_wph[_slot_wp].get("plan",{}).get("weekly",[]))
            if _slot_wp_exists and _slot_wp_src == "fallback_yfinance" and _bs_real_wp and not st.session_state.get(_wp_upg_key):
                _slot_wp_exists = False
                st.session_state[_wp_upg_key] = True
            if not _slot_wp_exists:
                st.session_state[_wp_auto_key] = True
                try:
                    # _sch_ensure_bs30: fallback otomatis jika bs30 kosong
                    _bs30_wp = _sch_ensure_bs30(_now_sch, _today_s)
                    _bs30_wp_src = "broker"
                    if _bsh_wp_chk:
                        _last_wp_k = sorted(_bsh_wp_chk.keys())[-1]
                        _bs30_wp_src = _bsh_wp_chk[_last_wp_k].get("source", "broker")
                    if _bs30_wp:
                        _tickers_wp = tuple(s["ticker"] for s in _bs30_wp if s.get("ticker"))
                        # Bug #4 fix: gunakan _reco_fetch_prices + _rule_based_plan_v2 untuk weekly
                        try:
                            _pm_wp = _reco_fetch_prices(_tickers_wp)
                        except Exception:
                            _pm_wp = {}
                        if _pm_wp:
                            _src_note_w = "" if _bs30_wp_src != "fallback_yfinance" else " · Screened via fallback (broker API limit)"
                            try:
                                _plan_wp = _rule_based_plan_v2(_pm_wp, _bs30_wp, "weekly")
                                if _plan_wp:
                                    _plan_wp["outlook"] = (_plan_wp.get("outlook") or "") + f" · Auto-generated Sabtu 12:00 WIB{_src_note_w}"
                            except Exception:
                                _plan_wp = None
                            if _plan_wp and _plan_wp.get("weekly"):
                                _wph_cur = st.session_state.get("auto_plan_history_weekly", {})
                                _gen_wp  = _now_sch.strftime("%d %b %Y, %H:%M WIB")
                                _wph_cur[_slot_wp] = {
                                    "date": _now_sch.strftime("%d %b %Y"),
                                    "slot": "Sabtu Siang (12:00)",
                                    "plan": _plan_wp,
                                    "generated_at": _gen_wp,
                                    "source": _bs30_wp_src,
                                }
                                st.session_state["auto_plan_history_weekly"] = _wph_cur
                                try:
                                    save_field(st.session_state.user["email"], "auto_plan_history_weekly", _wph_cur)
                                except Exception: pass
                except:
                    if _wp_auto_key in st.session_state:
                        del st.session_state[_wp_auto_key]

# Jalankan scheduler setiap page load
if st.session_state.get("user"):
    _sigma_run_global_scheduler()

# ── AUTO-REFRESH JAM BURSA ─────────────────────────────────────────
# Aktif 09:00–16:05 WIB, Senin–Jumat, interval 5 menit.
# Pakai st.fragment + time.sleep agar tidak block seluruh UI.
# Mekanisme: simpan timestamp refresh terakhir di session_state,
# bandingkan tiap rerun — kalau sudah lewat 5 menit → trigger rerun.
def _auto_refresh_bursa():
    """
    Trigger st.rerun() otomatis:
    - Jam bursa 09:00–16:05 WIB (interval 5 menit) → update harga realtime
    - After-hours scheduler windows (interval 10 menit):
        * 06:00–06:30 → daily review auto-generate
        * 15:35–16:10 → BSJP auto-generate window
        * 20:25–20:45 → brosum refresh
        * 20:55–21:15 → daily plan auto-generate
    """
    import time as _time_ar
    try:
        from datetime import timezone as _tz_ar, timedelta as _td_ar
        _wib_ar  = _tz_ar(_td_ar(hours=7))
        _now_ar  = datetime.now(_wib_ar)
        _wd_ar   = _now_ar.weekday()   # 0=Senin … 6=Minggu
        _h_ar    = _now_ar.hour
        _m_ar    = _now_ar.minute

        _is_weekday_ar = _wd_ar < 5

        # Window utama: jam bursa 09:00–16:05
        _is_bursa = (
            _is_weekday_ar and
            ((_h_ar == 9) or (_h_ar > 9 and _h_ar < 16) or
             (_h_ar == 16 and _m_ar <= 5))
        )

        # Window scheduler after-hours (hanya hari kerja kecuali daily review)
        _is_daily_review_window = _is_weekday_ar and (_h_ar == 6 and _m_ar <= 30)
        _is_bsjp_window         = _is_weekday_ar and ((_h_ar == 15 and _m_ar >= 35) or (_h_ar == 16 and _m_ar <= 10))
        _is_brosum_window       = _is_weekday_ar and (_h_ar == 20 and 25 <= _m_ar <= 45)
        _is_dailyplan_window    = _is_weekday_ar and ((_h_ar == 20 and _m_ar >= 55) or (_h_ar == 21 and _m_ar <= 15))

        _is_active = _is_bursa or _is_daily_review_window or _is_bsjp_window or _is_brosum_window or _is_dailyplan_window

        if not _is_active:
            return

        # Interval: 5 menit saat bursa, 10 menit saat after-hours
        _REFRESH_INTERVAL = 5 * 60 if _is_bursa else 10 * 60
        _last_key = "_auto_refresh_last_ts"
        _last_ts  = st.session_state.get(_last_key, 0)
        _now_ts   = _time_ar.time()

        if _now_ts - _last_ts >= _REFRESH_INTERVAL:
            # FIX B8: jangan rerun jika ada operasi berat sedang berjalan (Analyze, AI call)
            if st.session_state.get("_heavy_op_running"):
                return
            st.session_state[_last_key] = _now_ts
            _jam_str = _now_ar.strftime("%H:%M")
            if _is_bursa:
                st.toast(f"🔄 Data diperbarui otomatis · {_jam_str} WIB", icon="📈")
            else:
                st.toast(f"⚙️ Scheduler check · {_jam_str} WIB", icon="🕐")
            st.rerun()
    except Exception:
        pass  # auto-refresh gagal → tidak crash app

if st.session_state.get("user"):
    _auto_refresh_bursa()


