            info = _com_data.get(name, {"price": 0, "pct": 0.0})
            px = info["price"]; pct = info["pct"]
            if px == 0: px_str = "N/A"
            elif name == "USD/IDR": px_str = f"Rp {px:,.0f}"
            elif name in ("BTC/USD", "ETH/USD"): px_str = f"${px:,.0f}"
